def _normalizar_patente(valor):
    texto = unicodedata.normalize('NFKD', str(valor or ''))
    texto = ''.join(caracter for caracter in texto if not unicodedata.combining(caracter))
    return re.sub(r'[^A-Z0-9]', '', texto.upper())


def _debug_ticket_pesaje(mensaje, **datos):
    detalle = ' | '.join(f'{clave}={valor}' for clave, valor in datos.items())
    texto = f'[OP_TICKET_PESAJE] {mensaje}'
    if detalle:
        texto = f'{texto} | {detalle}'
    logger.info(texto)
    if getattr(settings, 'DEBUG', False):
        print(texto)


def _normalizar_observacion_ticket(valor):
    return re.sub(r'[\s\-]+', '', str(valor or '').strip().upper())


def _tipo_ticket_pesaje(paso_nombre):
    return PASOS_OPERACION_PLANTA_TICKET.get(str(paso_nombre or '').strip())


def _codigo_campo_ticket_pesaje(tipo_ticket):
    return f'OP_TICKET_PESAJE_{tipo_ticket}'


def _fecha_ticket_desde_nombre(nombre_archivo):
    nombre = os.path.basename(str(nombre_archivo or ''))
    match = re.search(
        r'COM_(?:ENT|SAL)_[A-Z0-9]+_(\d{2})_(\d{2})_(\d{2})_(\d{2})_(\d{2})(?:_(\d{8})_(\d{6}))?\.pdf$',
        nombre,
        re.IGNORECASE
    )
    if not match:
        return None
    yy, mes, dia, hora, minuto, fecha_larga, hora_larga = match.groups()
    try:
        if fecha_larga and hora_larga:
            return datetime.strptime(fecha_larga + hora_larga, '%Y%m%d%H%M%S')
        return datetime(2000 + int(yy), int(mes), int(dia), int(hora), int(minuto))
    except ValueError:
        return None


def _buscar_ticket_pesaje_mas_reciente(patente, tipo_ticket):
    patente_normalizada = _normalizar_patente(patente)
    _debug_ticket_pesaje(
        'Inicio busqueda ticket',
        patente_original=repr(patente),
        patente_normalizada=patente_normalizada,
        tipo_ticket=tipo_ticket
    )
    if not patente_normalizada or tipo_ticket not in {'ENT', 'SAL'}:
        _debug_ticket_pesaje('Busqueda cancelada por patente o tipo invalido', patente=patente_normalizada, tipo_ticket=tipo_ticket)
        return None

    candidatos = []
    patron_ticket = re.compile(
        r'^COM_(ENT|SAL)_(.+?)_(\d{2})_(\d{2})_(\d{2})_(\d{2})_(\d{2})(?:_\d{8}_\d{6})?\.pdf$',
        re.IGNORECASE
    )
    for carpeta in [TICKET_PESAJE_SHARED_PATH, TICKET_PESAJE_LOCAL_PATH]:
        _debug_ticket_pesaje('Revisando carpeta tickets', carpeta=carpeta, existe=os.path.isdir(carpeta) if carpeta else False)
        if not carpeta or not os.path.isdir(carpeta):
            continue
        try:
            nombres_archivos = os.listdir(carpeta)
        except OSError as e:
            _debug_ticket_pesaje('No fue posible listar carpeta tickets', carpeta=carpeta, error=str(e))
            continue
        for nombre in nombres_archivos:
            match = patron_ticket.match(nombre)
            if not match:
                continue
            tipo_archivo = match.group(1).upper()
            patente_archivo = _normalizar_patente(match.group(2))
            if tipo_archivo != tipo_ticket or patente_archivo != patente_normalizada:
                continue
            ruta = os.path.join(carpeta, nombre)
            if not os.path.isfile(ruta):
                continue
            fecha_nombre = _fecha_ticket_desde_nombre(nombre) or datetime.min
            try:
                fecha_modificacion = datetime.fromtimestamp(os.path.getmtime(ruta))
            except OSError:
                fecha_modificacion = datetime.min
            candidatos.append((fecha_nombre, fecha_modificacion, ruta))
            _debug_ticket_pesaje(
                'Candidato ticket encontrado',
                archivo=nombre,
                patente_archivo=patente_archivo,
                fecha_nombre=fecha_nombre,
                fecha_modificacion=fecha_modificacion
            )

    if not candidatos:
        _debug_ticket_pesaje('Sin candidatos ticket', patente=patente_normalizada, tipo_ticket=tipo_ticket)
        return None
    candidatos.sort(key=lambda item: (item[0], item[1]), reverse=True)
    _debug_ticket_pesaje(
        'Ticket seleccionado',
        archivo=os.path.basename(candidatos[0][2]),
        ruta=candidatos[0][2],
        total_candidatos=len(candidatos)
    )
    return candidatos[0][2]


def _peso_entero(valor):
    texto = re.sub(r'[^0-9]', '', str(valor or ''))
    return int(texto) if texto else 0


def _extraer_folio_ticket_pesaje(lineas):
    for indice, linea in enumerate(lineas):
        if re.search(r'Folio\s+Nro', linea, re.IGNORECASE):
            bloque = lineas[indice + 1:indice + 10]
            for candidata in bloque:
                texto = candidata.strip()
                if re.fullmatch(r'\d{3,}', texto):
                    return texto
    texto_completo = '\n'.join(lineas)
    folio_match = re.search(r'Folio\s*Nro\.?\s*:?\s*(\d{3,})', texto_completo, re.IGNORECASE)
    return folio_match.group(1).strip() if folio_match else ''


def _filas_fecha_pesaje_ticket(lineas):
    filas = []
    patron_fecha_peso = re.compile(r'^\d{2}-\d{2}-\d{4}\s+\d{2}:\d{2}\s+([\d\.,]+)\b')
    for linea in lineas:
        if linea.startswith('01-01-1900'):
            continue
        match = patron_fecha_peso.search(linea)
        if match:
            filas.append({
                'linea': linea,
                'peso': _peso_entero(match.group(1)),
            })
    return filas


def _extraer_datos_ticket_pesaje(ruta_pdf, tipo_ticket):
    texto_paginas = []
    with open(ruta_pdf, 'rb') as archivo:
        reader = PdfReader(archivo)
        for page in reader.pages:
            texto_paginas.append(page.extract_text() or '')
    texto = '\n'.join(texto_paginas)
    lineas = [linea.strip() for linea in texto.splitlines() if linea.strip()]

    folio = _extraer_folio_ticket_pesaje(lineas)

    peso = 0
    filas_pesaje = _filas_fecha_pesaje_ticket(lineas)
    if tipo_ticket == 'ENT':
        if filas_pesaje:
            peso = filas_pesaje[0]['peso']
        if not peso:
            for linea in lineas:
                if re.search(r'\bEntrada\b', linea, re.IGNORECASE):
                    numeros = re.findall(r'\d[\d\.,]*', linea)
                    if numeros:
                        peso = _peso_entero(numeros[-1])
                        break
    elif tipo_ticket == 'SAL':
        pesos = []
        for linea in lineas:
            if re.search(r'Peso\s+Neto', linea, re.IGNORECASE) and not re.search(r'informado', linea, re.IGNORECASE):
                numeros = re.findall(r'\d[\d\.,]*', linea)
                if numeros:
                    pesos.append(_peso_entero(numeros[-1]))
        peso = next((valor for valor in reversed(pesos) if valor), 0)
        if not peso and len(filas_pesaje) > 1:
            peso = filas_pesaje[-1]['peso']

    observacion_match = re.search(r'\b([A-Z]{3,4}\d{6,7}(?:-\d)?)\b', texto.upper())
    observacion = _normalizar_observacion_ticket(observacion_match.group(1)) if observacion_match else ''

    if not folio:
        raise ValueError('No fue posible leer el folio del ticket de pesaje.')
    if not peso:
        raise ValueError('No fue posible leer un peso valido del ticket de pesaje.')

    return {
        'folio': folio,
        'peso_neto': peso,
        'observacion': observacion,
    }


def _ruta_ticket_permitida(ruta):
    try:
        ruta_real = os.path.realpath(os.path.abspath(ruta))
        local_real = os.path.realpath(os.path.abspath(TICKET_PESAJE_LOCAL_PATH))
        return ruta_real.startswith(local_real + os.sep) or ruta_real == local_real
    except (TypeError, ValueError, OSError):
        return False


def _copiar_ticket_local_si_necesario(ruta_pdf):
    os.makedirs(TICKET_PESAJE_LOCAL_PATH, exist_ok=True)
    destino = os.path.join(TICKET_PESAJE_LOCAL_PATH, os.path.basename(ruta_pdf))
    if os.path.realpath(os.path.abspath(ruta_pdf)) != os.path.realpath(os.path.abspath(destino)):
        if not os.path.exists(destino):
            shutil.copy2(ruta_pdf, destino)
        return destino
    return ruta_pdf


def _obtener_campo_ticket_pesaje(citacion, tipo_ticket, usuario):
    codigo = _codigo_campo_ticket_pesaje(tipo_ticket)
    campo, _ = CAMPO.objects.get_or_create(
        EP_NID=citacion.EP_NID,
        CA_CCODIGO=codigo,
        defaults={
            'US_NID': usuario,
            'CA_CTIPO': 'NUMERO',
            'CA_CETIQUETA': f'Ticket pesaje {tipo_ticket}',
            'CA_CPLACEMARK': 'Peso obtenido desde ticket',
            'CA_BOBLIGATORIO': True,
            'CA_BHABILITADO': True,
            'CA_BASIGNARVALOR': False,
        }
    )
    cambios = []
    if not campo.CA_BHABILITADO:
        campo.CA_BHABILITADO = True
        cambios.append('CA_BHABILITADO')
    if campo.CA_CTIPO != 'NUMERO':
        campo.CA_CTIPO = 'NUMERO'
        cambios.append('CA_CTIPO')
    if cambios:
        campo.save(update_fields=cambios)
    return campo


def _metadata_ticket_pesaje(citacion, paso, tipo_ticket, patente, ruta_local, datos, usuario):
    fecha_ticket = _fecha_ticket_desde_nombre(os.path.basename(ruta_local))
    return {
        'folio': datos['folio'],
        'peso_neto': datos['peso_neto'],
        'observacion': datos.get('observacion') or '',
        'ruta_real_pdf': os.path.abspath(ruta_local),
        'nombre_archivo_pdf': os.path.basename(ruta_local),
        'fecha_hora_ticket': fecha_ticket.isoformat() if fecha_ticket else '',
        'patente': _normalizar_patente(patente),
        'tipo_ticket': tipo_ticket,
        'citacion_id': citacion.id,
        'paso_operacion': paso,
        'usuario_id': usuario.id,
    }


def _dato_ticket_pesaje(citacion, paso):
    tipo_ticket = _tipo_ticket_pesaje(paso)
    if not tipo_ticket:
        return None
    return DATO_OPERACION.objects.filter(
        CI_NID=citacion,
        CAMP_NID__CA_CCODIGO=_codigo_campo_ticket_pesaje(tipo_ticket)
    ).select_related('CAMP_NID').order_by('-id').first()


def _leer_metadata_ticket_dato(dato):
    if not dato:
        return None
    try:
        metadata = json.loads(dato.DO_CVALOR or '{}')
    except (TypeError, ValueError):
        return None
    return metadata if isinstance(metadata, dict) else None


def _ticket_pesaje_obligatorio_guardado(citacion, paso):
    tipo_ticket = _tipo_ticket_pesaje(paso)
    if not tipo_ticket:
        return True
    dato = _dato_ticket_pesaje(citacion, paso)
    metadata = _leer_metadata_ticket_dato(dato)
    if not metadata:
        return False
    ruta_pdf = metadata.get('ruta_real_pdf')
    return all([
        metadata.get('folio'),
        int(metadata.get('peso_neto') or 0) > 0,
        metadata.get('tipo_ticket') == tipo_ticket,
        metadata.get('paso_operacion') == paso,
        ruta_pdf,
        os.path.isfile(ruta_pdf),
        _ruta_ticket_permitida(ruta_pdf),
    ])


def _payload_ticket_pesaje_guardado(citacion, paso, request=None):
    dato = _dato_ticket_pesaje(citacion, paso)
    metadata = _leer_metadata_ticket_dato(dato)
    if not dato or not metadata or not _ticket_pesaje_obligatorio_guardado(citacion, paso):
        return None
    download_url = reverse('ajax_operacion_planta_descargar_ticket_pesaje')
    url = f'{download_url}?dato_id={dato.id}'
    if request:
        url = request.build_absolute_uri(url)
    return {
        'dato_id': dato.id,
        'peso_neto': metadata.get('peso_neto') or dato.DO_NPESO,
        'folio': metadata.get('folio') or '',
        'observacion': metadata.get('observacion') or '',
        'download_url': url,
        'nombre_archivo_pdf': metadata.get('nombre_archivo_pdf') or '',
        'tipo_ticket': metadata.get('tipo_ticket') or '',
    }


def _observacion_cierre_ticket_pesaje(citacion, paso):
    ticket = _payload_ticket_pesaje_guardado(citacion, paso)
    if not ticket:
        return ''

    folio = ticket.get('folio') or 'Sin folio'
    peso = ticket.get('peso_neto') or ''
    archivo = ticket.get('nombre_archivo_pdf') or 'Sin archivo'
    if paso == 'Pesaje Salida':
        return f'Pesaje salida informado. Ticket: {folio} | Peso: {peso} | Archivo: {archivo}'
    if paso == 'Pesaje Entrada':
        return f'Pesaje entrada informado. Ticket: {folio} | Peso: {peso} | Archivo: {archivo}'
    return ''


def _config_accion_toma_muestra(nombre_flujo):
    flujo_normalizado = normalizar_nombre_flujo_operacion(nombre_flujo)
    if flujo_normalizado in {normalizar_nombre_flujo_operacion(flujo) for flujo in FLUJOS_TOMA_MUESTRA_VAPOR}:
        return {
            'tipo': 'vapor',
            'accion_label': 'Enviar a vapor',
            'estado_label': 'Camion enviado a vapor',
            'pendiente_label': 'Pendiente de envio a vapor',
            'mensaje_guardado': 'Camion enviado a vapor.',
            'log_operacion': 'TOMA_MUESTRA_ENVIA_VAPOR',
            'log_mensaje': 'Camion enviado a vapor en Toma de muestra',
        }
    return {
        'tipo': 'analisis',
        'accion_label': 'Enviar a analisis',
        'estado_label': 'Muestra enviada a analisis',
        'pendiente_label': 'Pendiente de envio a analisis',
        'mensaje_guardado': 'Muestra enviada a analisis.',
        'log_operacion': 'TOMA_MUESTRA_ENVIA_ANALISIS',
        'log_mensaje': 'Muestra enviada a analisis en Toma de muestra',
    }


def _obtener_campo_toma_muestra_accion(citacion, usuario):
    campo, _ = CAMPO.objects.get_or_create(
        EP_NID=citacion.EP_NID,
        CA_CCODIGO=CAMPO_TOMA_MUESTRA_ACCION,
        defaults={
            'US_NID': usuario,
            'CA_CTIPO': 'CHECK',
            'CA_CETIQUETA': 'Accion toma de muestra',
            'CA_CPLACEMARK': 'Evento operacional de toma de muestra',
            'CA_BOBLIGATORIO': True,
            'CA_BHABILITADO': True,
            'CA_BASIGNARVALOR': False,
        }
    )
    if not campo.CA_BHABILITADO:
        campo.CA_BHABILITADO = True
        campo.save(update_fields=['CA_BHABILITADO'])
    return campo


def _dato_toma_muestra_accion(citacion):
    return DATO_OPERACION.objects.filter(
        CI_NID=citacion,
        CAMP_NID__CA_CCODIGO__in=[CAMPO_TOMA_MUESTRA_ACCION, CAMPO_TOMA_MUESTRA_VAPOR_LEGACY]
    ).select_related('CAMP_NID').order_by('-id').first()


def _leer_metadata_toma_muestra_accion(citacion):
    dato = _dato_toma_muestra_accion(citacion)
    if not dato:
        return None
    try:
        metadata = json.loads(dato.DO_CVALOR or '{}')
    except (TypeError, ValueError):
        return None
    if not isinstance(metadata, dict) or not (metadata.get('accion_registrada') or metadata.get('enviado_vapor')):
        return None
    if metadata.get('enviado_vapor') and not metadata.get('tipo_accion'):
        metadata['tipo_accion'] = 'vapor'
        metadata['mensaje'] = metadata.get('mensaje') or 'Camion enviado a vapor'
    metadata['dato_id'] = dato.id
    return metadata


def _actualizar_observacion_toma_muestra_accion(citacion, observacion):
    dato = _dato_toma_muestra_accion(citacion)
    if not dato:
        return
    try:
        metadata = json.loads(dato.DO_CVALOR or '{}')
    except (TypeError, ValueError):
        return
    if not isinstance(metadata, dict):
        return
    metadata['observacion'] = str(observacion or '').strip()
    dato.DO_CVALOR = json.dumps(metadata, ensure_ascii=False)
    dato.save(update_fields=['DO_CVALOR'])


def _obtener_campo_observacion_etapa(citacion, usuario):
    campo, _ = CAMPO.objects.get_or_create(
        EP_NID=citacion.EP_NID,
        CA_CCODIGO=CAMPO_OBSERVACION_ETAPA,
        defaults={
            'US_NID': usuario,
            'CA_CTIPO': 'TEXTO',
            'CA_CETIQUETA': 'Observacion etapa operacional',
            'CA_CPLACEMARK': 'Observacion independiente por etapa de Operacion Planta',
            'CA_BOBLIGATORIO': False,
            'CA_BHABILITADO': True,
            'CA_BASIGNARVALOR': False,
        }
    )
    if not campo.CA_BHABILITADO:
        campo.CA_BHABILITADO = True
        campo.save(update_fields=['CA_BHABILITADO'])
    return campo


def _metadata_observacion_etapa(citacion, paso_operacion, observacion, usuario):
    ahora = timezone.now()
    return {
        'citacion_id': citacion.id,
        'paso_operacion': str(paso_operacion or '').strip(),
        'observacion': str(observacion or '').strip(),
        'usuario_id': usuario.id,
        'usuario': usuario.username,
        'fecha_hora': timezone.localtime(ahora).strftime('%d/%m/%Y %H:%M'),
        'fecha_iso': ahora.isoformat(),
    }


def _registrar_observacion_etapa(citacion, paso_operacion, observacion, usuario):
    metadata = _metadata_observacion_etapa(citacion, paso_operacion, observacion, usuario)
    campo = _obtener_campo_observacion_etapa(citacion, usuario)
    DATO_OPERACION.objects.create(
        CI_NID=citacion,
        SC_NID=citacion.SC_NID,
        ET_NID=citacion.ETAPA_ACTUAL,
        CAMP_NID=campo,
        EP_NID=citacion.EP_NID,
        US_NID=usuario,
        DO_CVALOR=json.dumps(metadata, ensure_ascii=False),
        DO_FFECHAREGISTRO=timezone.now(),
    )
    return metadata


def _leer_metadata_observacion_etapa(citacion, paso_operacion):
    paso_operacion = str(paso_operacion or '').strip()
    if not paso_operacion:
        return None
    registros = DATO_OPERACION.objects.filter(
        CI_NID=citacion,
        CAMP_NID__CA_CCODIGO=CAMPO_OBSERVACION_ETAPA
    ).select_related('CAMP_NID', 'US_NID').order_by('-DO_FFECHAREGISTRO', '-id')
    for dato in registros:
        try:
            metadata = json.loads(dato.DO_CVALOR or '{}')
        except (TypeError, ValueError):
            continue
        if not isinstance(metadata, dict):
            continue
        if str(metadata.get('paso_operacion') or '').strip() == paso_operacion:
            return metadata
    return None


def _observacion_etapa_visible(citacion, paso_operacion):
    metadata = _leer_metadata_observacion_etapa(citacion, paso_operacion) or {}
    return str(metadata.get('observacion') or '').strip()


def _observacion_toma_muestra_visible(citacion, log_toma_muestra=None):
    observacion_log = _observacion_visible_operacion(
        PASO_TOMA_MUESTRA,
        log_toma_muestra.OPL_COBSERVACION if log_toma_muestra else ''
    )
    if observacion_log:
        return observacion_log

    observacion_independiente = _leer_metadata_observacion_etapa(citacion, PASO_TOMA_MUESTRA)
    if observacion_independiente is not None:
        return str(observacion_independiente.get('observacion') or '').strip()

    metadata = _leer_metadata_toma_muestra_accion(citacion) or {}
    return str(metadata.get('observacion') or '').strip()


def _insumo_operacion_planta(citacion):
    detalle = obtener_detalle_operacional_citacion(citacion)
    if detalle and detalle.CDO_CINSUMO:
        return detalle.CDO_CINSUMO
    citacion_item = CITACION_ITEM.objects.select_related('IT_NID').filter(CI_NID=citacion).first()
    if citacion_item and citacion_item.IT_NID:
        return citacion_item.IT_NID.IT_CNOMBRE or ''
    return ''


def _codigo_sap_operacion_planta(citacion):
    detalle = obtener_detalle_operacional_citacion(citacion)
    if detalle and detalle.CDO_CCODIGO_SAP:
        return detalle.CDO_CCODIGO_SAP
    citacion_item = CITACION_ITEM.objects.select_related('IT_NID').filter(CI_NID=citacion).first()
    if citacion_item and citacion_item.IT_NID:
        return citacion_item.IT_NID.IT_CCODIGO or ''
    return ''


def _fecha_ingreso_operacion_planta(citacion):
    log_ingreso = SYSLOGGER.objects.filter(
        LOG_COPERACION='AUTORIZA_INGRESO_PLANTA',
        LOG_CADD1=str(citacion.id)
    ).order_by('-LOG_FFECHAREGISTRO').first()
    fecha = (
        log_ingreso.LOG_FFECHAREGISTRO if log_ingreso and log_ingreso.LOG_FFECHAREGISTRO
        else (citacion.CI_FFECHAINICIO or citacion.CI_FFECHACITACION)
    )
    if fecha and timezone.is_naive(fecha):
        fecha = timezone.make_aware(fecha, timezone.get_current_timezone())
    return timezone.localtime(fecha).strftime('%d/%m/%Y %H:%M') if fecha else ''


def _guia_operacion_planta_url(citacion, documentos_operacion):
    documento_guia = CITACION_DOCUMENTO.objects.filter(
        CI_NID=citacion,
        EP_NID=citacion.EP_NID,
        CD_CTIPO=CITACION_DOCUMENTO.TIPO_GUIA,
        CD_BACTIVO=True
    ).order_by('-CD_FFECHASUBIDA', '-id').first()
    if documento_guia:
        return reverse('expediente_citacion_documento_ver', args=[documento_guia.id])

    for documento in documentos_operacion:
        etiqueta = f"{documento.get('label', '')} {documento.get('nombre_archivo', '')}".lower()
        if 'guia' in etiqueta or 'guía' in etiqueta:
            return documento.get('download_url') or ''
    return ''


def _toma_muestra_accion_guardada(citacion):
    return bool(_leer_metadata_toma_muestra_accion(citacion))


def _payload_toma_muestra_accion(citacion, nombre_flujo):
    config = _config_accion_toma_muestra(nombre_flujo)
    metadata = _leer_metadata_toma_muestra_accion(citacion)
    if not metadata:
        return {
            **config,
            'registrada': False,
            'usuario': '',
            'fecha': '',
            'observacion': '',
        }
    return {
        **config,
        'registrada': True,
        'tipo': metadata.get('tipo_accion') or config['tipo'],
        'usuario': metadata.get('usuario') or '',
        'fecha': metadata.get('fecha') or '',
        'observacion': metadata.get('observacion') or '',
        'mensaje': metadata.get('mensaje') or config['estado_label'],
    }


def _registrar_toma_muestra_accion(citacion, usuario, nombre_flujo, observacion=''):
    config = _config_accion_toma_muestra(nombre_flujo)
    campo = _obtener_campo_toma_muestra_accion(citacion, usuario)
    fecha = timezone.localtime(timezone.now())
    metadata = {
        'accion_registrada': True,
        'tipo_accion': config['tipo'],
        'citacion_id': citacion.id,
        'paso_operacion': PASO_TOMA_MUESTRA,
        'mensaje': config['estado_label'],
        'observacion': observacion,
        'usuario_id': usuario.id,
        'usuario': usuario.username,
        'fecha': fecha.strftime('%d/%m/%Y %H:%M'),
        'fecha_iso': fecha.isoformat(),
    }
    dato, _ = DATO_OPERACION.objects.update_or_create(
        CI_NID=citacion,
        CAMP_NID=campo,
        defaults={
            'EP_NID': citacion.EP_NID,
            'US_NID': usuario,
            'SC_NID': citacion.SC_NID,
            'ET_NID': citacion.ETAPA_ACTUAL,
            'DO_CVALOR': json.dumps(metadata, ensure_ascii=False),
            'DO_NPESO': None,
            'DO_FFECHAREGISTRO': timezone.now(),
        }
    )
    metadata['dato_id'] = dato.id
    registrar_log_camion_no_planificado(
        usuario,
        citacion.EP_NID,
        config['log_operacion'],
        f'{config["log_mensaje"]} para citacion #{citacion.id}.',
        citacion.id,
        ''
    )
    return metadata


def _obtener_campo_tiempo_vapor(citacion, usuario):
    campo, _ = CAMPO.objects.get_or_create(
        EP_NID=citacion.EP_NID,
        CA_CCODIGO=CAMPO_TOMA_MUESTRA_TIEMPO_VAPOR,
        defaults={
            'US_NID': usuario,
            'CA_CTIPO': 'TEXTO',
            'CA_CETIQUETA': 'Tiempo vapor',
            'CA_CPLACEMARK': 'Metadata operacional de tiempo en vapor',
            'CA_BOBLIGATORIO': False,
            'CA_BHABILITADO': True,
            'CA_BASIGNARVALOR': False,
        }
    )
    cambios = []
    if not campo.CA_BHABILITADO:
        campo.CA_BHABILITADO = True
        cambios.append('CA_BHABILITADO')
    if campo.CA_CTIPO != 'TEXTO':
        campo.CA_CTIPO = 'TEXTO'
        cambios.append('CA_CTIPO')
    if cambios:
        campo.save(update_fields=cambios)
    return campo


def _dato_tiempo_vapor(citacion):
    return DATO_OPERACION.objects.filter(
        CI_NID=citacion,
        CAMP_NID__CA_CCODIGO=CAMPO_TOMA_MUESTRA_TIEMPO_VAPOR
    ).select_related('CAMP_NID').order_by('-id').first()


def _leer_metadata_tiempo_vapor(citacion):
    dato = _dato_tiempo_vapor(citacion)
    if not dato:
        return None
    try:
        metadata = json.loads(dato.DO_CVALOR or '{}')
    except (TypeError, ValueError):
        return None
    if not isinstance(metadata, dict):
        return None
    metadata['dato_id'] = dato.id
    return metadata


def _metadata_tiempo_vapor_desde_accion(citacion):
    metadata_accion = _leer_metadata_toma_muestra_accion(citacion)
    if not metadata_accion:
        return None
    if str(metadata_accion.get('tipo_accion') or '').strip().lower() != 'vapor':
        return None

    inicio = metadata_accion.get('fecha_iso') or ''
    if not inicio:
        dato_accion = _dato_toma_muestra_accion(citacion)
        if dato_accion and dato_accion.DO_FFECHAREGISTRO:
            inicio = dato_accion.DO_FFECHAREGISTRO.isoformat()
    if not inicio:
        return None

    return {
        'inicio_vapor': inicio,
        'fin_vapor': '',
        'duracion_segundos': None,
        'duracion_legible': '',
        'usuario_inicio': metadata_accion.get('usuario') or '',
        'usuario_fin': '',
        'usuario_inicio_id': metadata_accion.get('usuario_id'),
        'usuario_fin_id': None,
        'citacion_id': citacion.id,
        'paso_operacion': PASO_TOMA_MUESTRA,
        'origen_inicio': 'accion_toma_muestra',
    }


def _guardar_metadata_tiempo_vapor(citacion, usuario, metadata):
    campo = _obtener_campo_tiempo_vapor(citacion, usuario)
    dato, _ = DATO_OPERACION.objects.update_or_create(
        CI_NID=citacion,
        CAMP_NID=campo,
        defaults={
            'EP_NID': citacion.EP_NID,
            'US_NID': usuario,
            'SC_NID': citacion.SC_NID,
            'ET_NID': citacion.ETAPA_ACTUAL,
            'DO_CVALOR': json.dumps(metadata, ensure_ascii=False),
            'DO_NPESO': None,
            'DO_FFECHAREGISTRO': timezone.now(),
        }
    )
    metadata['dato_id'] = dato.id
    return metadata


def _payload_tiempo_vapor(citacion):
    """
    Construye el estado actual del tiempo de vapor para una citación.

    El estado se obtiene únicamente desde el registro específico del
    cronómetro de vapor. La acción operativa de enviar a vapor no debe
    considerarse como inicio automático del contador.
    """
    metadata = _leer_metadata_tiempo_vapor(citacion) or {}

    inicio = _parse_iso_operacion(metadata.get('inicio_vapor'))
    fin = _parse_iso_operacion(metadata.get('fin_vapor'))

    duracion_segundos = metadata.get('duracion_segundos')
    duracion_legible = metadata.get('duracion_legible') or ''

    if inicio:
        if fin:
            duracion_calculada = fin - inicio
        else:
            duracion_calculada = timezone.now() - inicio

        if duracion_segundos is None:
            duracion_segundos = max(
                int(duracion_calculada.total_seconds()),
                0,
            )

        if not duracion_legible:
            duracion_legible = formatear_duracion_operacional(
                duracion_calculada
            )

    return {
        'inicio_vapor': metadata.get('inicio_vapor') or '',
        'inicio_vapor_legible': (
            timezone.localtime(inicio).strftime('%d/%m/%Y %H:%M')
            if inicio
            else ''
        ),
        'fin_vapor': metadata.get('fin_vapor') or '',
        'fin_vapor_legible': (
            timezone.localtime(fin).strftime('%d/%m/%Y %H:%M')
            if fin
            else ''
        ),
        'duracion_segundos': duracion_segundos,
        'duracion_legible': duracion_legible,
        'usuario_inicio': metadata.get('usuario_inicio') or '',
        'usuario_fin': metadata.get('usuario_fin') or '',
        'en_proceso': bool(inicio and not fin),
        'finalizada': bool(inicio and fin),
        'iniciada': bool(inicio),
    }

def _iniciar_tiempo_vapor(citacion, usuario):
    """
    Inicia el contador de vapor para la citación actual.

    El contador solo se considera iniciado cuando existe metadata específica
    guardada por este proceso. La acción operativa "enviar a vapor" no debe
    iniciar ni bloquear automáticamente el cronómetro.
    """
    metadata = _leer_metadata_tiempo_vapor(citacion) or {}

    if metadata.get('fin_vapor'):
        raise ValueError('El tiempo de vapor ya fue finalizado.')

    if metadata.get('inicio_vapor'):
        raise ValueError(
            'La citación ya tiene un tiempo de vapor activo.'
        )

    ahora = timezone.now()

    metadata = {
        'inicio_vapor': ahora.isoformat(),
        'fin_vapor': '',
        'duracion_segundos': None,
        'duracion_legible': '',
        'usuario_inicio': usuario.username,
        'usuario_fin': '',
        'usuario_inicio_id': usuario.id,
        'usuario_fin_id': None,
        'citacion_id': citacion.id,
        'paso_operacion': PASO_TOMA_MUESTRA,
    }

    metadata = _guardar_metadata_tiempo_vapor(
        citacion=citacion,
        usuario=usuario,
        metadata=metadata,
    )

    OPERACION_PLANTA_LOG.objects.create(
        US_NID=usuario,
        EP_NID=citacion.EP_NID,
        PL_NID=citacion.PL_NID,
        CI_NID=citacion,
        OPL_CPASO='TOMA_MUESTRA_INICIO_VAPOR',
        OPL_CPERFIL_RESPONSABLE='ASISTENTE C D',
        OPL_CESTADO=OPERACION_PLANTA_LOG.ESTADO_COMPLETADO,
        OPL_COBSERVACION='Inicio manual del tiempo de vapor',
    )

    return metadata

def _finalizar_tiempo_vapor(citacion, usuario):
    """
    Finaliza el contador de vapor de la citación actual.

    Solo utiliza la metadata específica del cronómetro de vapor.
    La acción operativa "enviar a vapor" no se considera como inicio
    válido del contador.
    """
    metadata = _leer_metadata_tiempo_vapor(citacion)

    if not metadata or not metadata.get('inicio_vapor'):
        raise ValueError(
            'Debe iniciar el tiempo de vapor antes de finalizar.'
        )

    if metadata.get('fin_vapor'):
        return metadata, None

    inicio = _parse_iso_operacion(metadata.get('inicio_vapor'))

    if not inicio:
        raise ValueError(
            'La fecha de inicio del tiempo de vapor no es válida.'
        )

    ahora = timezone.now()
    duracion = ahora - inicio

    metadata.update({
        'fin_vapor': ahora.isoformat(),
        'duracion_segundos': max(
            int(duracion.total_seconds()),
            0,
        ),
        'duracion_legible': formatear_duracion_operacional(
            duracion
        ),
        'usuario_fin': usuario.username,
        'usuario_fin_id': usuario.id,
    })

    metadata = _guardar_metadata_tiempo_vapor(
        citacion=citacion,
        usuario=usuario,
        metadata=metadata,
    )

    payload_vapor = _payload_tiempo_vapor(citacion)

    observacion = (
        f'Inicio vapor: '
        f'{payload_vapor.get("inicio_vapor_legible") or "Sin inicio"} | '
        f'Fin vapor: '
        f'{timezone.localtime(ahora).strftime("%d/%m/%Y %H:%M")} | '
        f'Duracion: '
        f'{metadata.get("duracion_legible") or "No disponible"} | '
        f'Usuario inicio: '
        f'{metadata.get("usuario_inicio") or ""} | '
        f'Usuario fin: '
        f'{metadata.get("usuario_fin") or ""}'
    )

    log = OPERACION_PLANTA_LOG.objects.create(
        US_NID=usuario,
        EP_NID=citacion.EP_NID,
        PL_NID=citacion.PL_NID,
        CI_NID=citacion,
        OPL_CPASO='TOMA_MUESTRA_FIN_VAPOR',
        OPL_CPERFIL_RESPONSABLE='ASISTENTE C D',
        OPL_CESTADO=OPERACION_PLANTA_LOG.ESTADO_COMPLETADO,
        OPL_COBSERVACION=observacion,
    )

    return metadata, log

