def _payload_resultado_calidad(citacion):
    registro = RESULTADO_CALIDAD_OPERACION.objects.filter(CI_NID=citacion).first()
    if registro:
        payload = serializar_resultado_calidad(registro)
        payload.update({
            'fecha_hora': payload.get('ultimo_cambio') or '',
            'documento_nombre': '',
            'documento_ruta': '',
            'download_url': '',
        })
        return payload
    metadata = _leer_metadata_resultado_calidad(citacion)
    if not metadata:
        return None
    download_url = ''
    if metadata.get('documento_ruta') and metadata.get('documento_nombre'):
        download_url = reverse('ajax_operacion_planta_descargar_documento_calidad')
        download_url = f'{download_url}?citacion_id={citacion.id}'
    comentario = str(metadata.get('comentario') or '').strip()
    if not comentario:
        comentario = _observacion_etapa_visible(citacion, PASO_ANALISIS_CALIDAD)
    return {
        'resultado_calidad': metadata.get('resultado_calidad') or '',
        'comentario': comentario,
        'documento_nombre': metadata.get('documento_nombre') or '',
        'documento_ruta': metadata.get('documento_ruta') or '',
        'download_url': download_url,
        'usuario': metadata.get('usuario') or '',
        'fecha_hora': metadata.get('fecha_hora') or '',
    }


def _observacion_visible_operacion(nombre_paso, observacion):
    observacion = str(observacion or '').strip()
    if not observacion:
        return ''

    if nombre_paso in PASOS_OPERACION_PLANTA_TICKET:
        observacion_normalizada = re.sub(r'[^A-Z0-9]+', ' ', observacion.upper()).strip()
        if re.match(r'^PESAJE (ENTRADA|SALIDA) INFORMADO TICKET\b', observacion_normalizada):
            return ''

    try:
        metadata = json.loads(observacion)
    except (TypeError, ValueError):
        return observacion

    if not isinstance(metadata, dict):
        return observacion

    if nombre_paso == PASO_ANALISIS_CALIDAD:
        return str(metadata.get('comentario') or '').strip()

    for llave in ('comentario', 'observaciones_descarga', 'observacion'):
        valor = metadata.get(llave)
        if valor:
            return str(valor).strip()
    return ''


def _guardar_documento_resultado_calidad(citacion, archivo):
    if not archivo:
        return '', ''
    carpeta = os.path.join(TICKET_PESAJE_LOCAL_PATH, 'calidad', str(citacion.id))
    os.makedirs(carpeta, exist_ok=True)
    nombre_base = get_valid_filename(os.path.basename(archivo.name or 'resultado_calidad'))
    timestamp = timezone.localtime(timezone.now()).strftime('%Y%m%d_%H%M%S')
    nombre_archivo = f'{timestamp}_{nombre_base}'
    ruta_archivo = os.path.join(carpeta, nombre_archivo)
    with open(ruta_archivo, 'wb+') as destino:
        for chunk in archivo.chunks():
            destino.write(chunk)
    return nombre_archivo, ruta_archivo


