def usuario_puede_operar_ingreso_camion(user):
    return getattr(user, 'is_superuser', False) or usuario_es_ingreso_camion(user)


def obtener_base_folder_campo(empresa_id):
    if empresa_id == ID_TERRAMAR:
        return CAMPO_TERRAMAR_PATH
    if empresa_id == ID_ACEITES_SBH:
        return CAMPO_ACEITES_PATH
    return CAMPO_TERRAMAR_PATH


def guardar_archivo_dato_operacion(citacion, etapa, archivo):
    base_folder = obtener_base_folder_campo(citacion.EP_NID_id)
    folder_path = os.path.join(base_folder, str(citacion.SC_NID.SE_CCODIGO), str(etapa.ET_CCODIGO))
    os.makedirs(folder_path, exist_ok=True)

    file_extension = archivo.name.split('.')[-1]
    unique_filename = str(uuid.uuid4()) + '.' + file_extension
    file_path = os.path.join(folder_path, unique_filename)

    with open(file_path, 'wb+') as destination:
        for chunk in archivo.chunks():
            destination.write(chunk)

    return file_path


EXPEDIENTE_CITACION_ROOT = os.path.join(settings.MEDIA_ROOT, 'documentos_citaciones')
EXPEDIENTE_CAMPO_TIPO = {
    'ING_DOC_GUIA': CITACION_DOCUMENTO.TIPO_GUIA,
    'ING_DOC_TICKET_ORIGEN': CITACION_DOCUMENTO.TIPO_TICKET_ORIGEN,
    'ING_DOC_SERNAPESCA': CITACION_DOCUMENTO.TIPO_SERNAPESCA,
}
EXPEDIENTE_TIPO_LABELS = {
    CITACION_DOCUMENTO.TIPO_GUIA: 'Guia',
    CITACION_DOCUMENTO.TIPO_TICKET_ORIGEN: 'Ticket origen',
    CITACION_DOCUMENTO.TIPO_SERNAPESCA: 'Sernapesca',
}


def usuario_puede_administrar_expediente(user):
    return getattr(user, 'is_superuser', False)


def obtener_nombre_archivo_expediente(tipo_documento, archivo):
    nombre_original = get_valid_filename(os.path.basename(archivo.name or 'documento'))
    extension = os.path.splitext(nombre_original)[1]
    prefijo = tipo_documento.lower()
    return f'{prefijo}_{uuid.uuid4()}{extension}'


def guardar_archivo_expediente_citacion(citacion, tipo_documento, archivo):
    folder_path = os.path.join(EXPEDIENTE_CITACION_ROOT, f'CITACION_{citacion.id}')
    os.makedirs(folder_path, exist_ok=True)

    nombre_archivo = obtener_nombre_archivo_expediente(tipo_documento, archivo)
    file_path = os.path.join(folder_path, nombre_archivo)

    with open(file_path, 'wb+') as destination:
        for chunk in archivo.chunks():
            destination.write(chunk)

    return file_path, nombre_archivo


def registrar_documento_expediente(citacion, tipo_documento, ruta_archivo, nombre_archivo, usuario, dato_operacion=None):
    fecha_modificacion = timezone.now()
    CITACION_DOCUMENTO.objects.filter(
        CI_NID=citacion,
        EP_NID=citacion.EP_NID,
        CD_CTIPO=tipo_documento,
        CD_BACTIVO=True
    ).update(
        CD_BACTIVO=False,
        CD_FFECHAMODIFICACION=fecha_modificacion,
        US_MODIFICA_NID=usuario
    )

    documento = CITACION_DOCUMENTO.objects.create(
        CI_NID=citacion,
        EP_NID=citacion.EP_NID,
        DO_NID=dato_operacion,
        CD_CTIPO=tipo_documento,
        CD_CRUTA_ARCHIVO=ruta_archivo,
        CD_CNOMBRE_ARCHIVO=nombre_archivo,
        US_SUBE_NID=usuario,
    )

    registrar_log_camion_no_planificado(
        usuario,
        citacion.EP_NID,
        'DOC_CIT_CARGA',
        f'Documento {tipo_documento} cargado en expediente de citacion #{citacion.id}',
        citacion.id,
        tipo_documento
    )
    return documento


def sincronizar_expediente_legacy_citacion(citacion, usuario=None):
    datos = DATO_OPERACION.objects.select_related('CAMP_NID', 'US_NID').filter(
        CI_NID=citacion,
        EP_NID=citacion.EP_NID,
        CAMP_NID__CA_CCODIGO__in=EXPEDIENTE_CAMPO_TIPO.keys()
    ).exclude(DO_CVALOR='')

    for dato in datos:
        tipo_documento = EXPEDIENTE_CAMPO_TIPO.get(dato.CAMP_NID.CA_CCODIGO)
        if not tipo_documento or not dato.DO_CVALOR:
            continue
        if CITACION_DOCUMENTO.objects.filter(DO_NID=dato).exists():
            continue
        if CITACION_DOCUMENTO.objects.filter(
            CI_NID=citacion,
            CD_CTIPO=tipo_documento,
            CD_BACTIVO=True
        ).exists():
            continue
        CITACION_DOCUMENTO.objects.create(
            CI_NID=citacion,
            EP_NID=citacion.EP_NID,
            DO_NID=dato,
            CD_CTIPO=tipo_documento,
            CD_CRUTA_ARCHIVO=dato.DO_CVALOR,
            CD_CNOMBRE_ARCHIVO=os.path.basename(dato.DO_CVALOR),
            US_SUBE_NID=dato.US_NID,
        )


def sincronizar_expedientes_legacy_empresa(empresa_id, limite=500):
    citaciones_ids = DATO_OPERACION.objects.filter(
        EP_NID_id=empresa_id,
        CAMP_NID__CA_CCODIGO__in=EXPEDIENTE_CAMPO_TIPO.keys()
    ).exclude(DO_CVALOR='').values_list('CI_NID_id', flat=True).distinct()[:limite]

    for citacion in CITACION.objects.filter(id__in=list(citaciones_ids)).select_related('EP_NID'):
        sincronizar_expediente_legacy_citacion(citacion)


def asegurar_campos_ingreso_camion(citacion, etapa, usuario):
    for indice, definicion in enumerate(CAMPOS_INGRESO_CAMION_DEFAULT, start=1):
        if es_citacion_despacho(citacion) and definicion['codigo'] == 'ING_BL':
            continue

        campo = CAMPO.objects.filter(
            EP_NID=citacion.EP_NID,
            CA_CCODIGO=definicion['codigo']
        ).first()

        if not campo:
            campo = CAMPO.objects.create(
                EP_NID=citacion.EP_NID,
                US_NID=usuario,
                CA_CTIPO=definicion['tipo'],
                CA_CCODIGO=definicion['codigo'],
                CA_CETIQUETA=definicion['etiqueta'],
                CA_CPLACEMARK=definicion['etiqueta'],
                CA_BOBLIGATORIO=definicion['obligatorio'],
                CA_BHABILITADO=True,
                CA_BASIGNARVALOR=definicion['asignar_citacion'],
            )
        elif definicion['codigo'] in ['ING_CANTIDAD_EJES', 'ING_TELEFONO_CONDUCTOR']:
            campos_actualizados = []
            if campo.CA_CTIPO != definicion['tipo']:
                campo.CA_CTIPO = definicion['tipo']
                campos_actualizados.append('CA_CTIPO')
            if campo.CA_CETIQUETA != definicion['etiqueta']:
                campo.CA_CETIQUETA = definicion['etiqueta']
                campos_actualizados.append('CA_CETIQUETA')
            if campo.CA_CPLACEMARK != definicion['etiqueta']:
                campo.CA_CPLACEMARK = definicion['etiqueta']
                campos_actualizados.append('CA_CPLACEMARK')
            if not campo.CA_BOBLIGATORIO:
                campo.CA_BOBLIGATORIO = True
                campos_actualizados.append('CA_BOBLIGATORIO')
            if campos_actualizados:
                campo.save(update_fields=campos_actualizados)

        DETALLE_ETAPA.objects.update_or_create(
            EP_NID=citacion.EP_NID,
            ET_NID=etapa,
            CAMP_NID=campo,
            defaults={
                'US_NID': usuario,
                'DET_NPASO': indice,
                'DET_BOBLIGATORIO': definicion['obligatorio'],
                'DET_CETIQUETAETAPA': definicion['etiqueta'],
                'DET_BHABILITADO': True,
            }
        )


def obtener_bl_inicial_citacion(citacion):
    if es_citacion_despacho(citacion):
        return ''

    detalle = obtener_detalle_operacional_citacion(citacion)
    if detalle:
        return detalle.CDO_CBL_CONTENEDOR or ''

    if not citacion.CI_CCOMENTARIO:
        return ''

    comentario = obtener_comentario_json_citacion(citacion)
    if not comentario:
        return ''

    return (
        comentario.get('bl')
        or comentario.get('BL')
        or comentario.get('contenedor')
        or comentario.get('BL / Contenedor')
        or ''
    )


def obtener_campos_operacion_etapa(citacion, etapa, usuario):
    asegurar_campos_ingreso_camion(citacion, etapa, usuario)

    campos = []
    detalles = DETALLE_ETAPA.objects.filter(
        EP_NID=citacion.EP_NID,
        ET_NID=etapa,
        DET_BHABILITADO=True,
        CAMP_NID__CA_BHABILITADO=True
    ).select_related('CAMP_NID').order_by('DET_NPASO', 'id')

    for detalle in detalles:
        campo = detalle.CAMP_NID
        if es_citacion_despacho(citacion) and campo.CA_CCODIGO == 'ING_BL':
            continue

        datos = []
        if campo.CA_CTIPO.lower() == 'lista' and campo.CA_CQUERY:
            try:
                datos = QueryParam(campo.CA_CQUERY)
            except Exception as e:
                print(f'Error al ejecutar query de campo {campo.id}: {e}')
        if campo.CA_CCODIGO == 'ING_CANTIDAD_EJES':
            datos = next(
                (definicion.get('opciones', []) for definicion in CAMPOS_INGRESO_CAMION_DEFAULT if definicion['codigo'] == 'ING_CANTIDAD_EJES'),
                []
            )

        dato_operacion = DATO_OPERACION.objects.filter(
            CI_NID=citacion,
            SC_NID=citacion.SC_NID,
            ET_NID=etapa,
            CAMP_NID=campo
        ).order_by('-id').first()

        valor_default = dato_operacion.DO_CVALOR if dato_operacion else (campo.CA_CVALORDEFAULT or '')
        if not dato_operacion and campo.CA_CCODIGO == 'ING_BL':
            valor_default = obtener_bl_inicial_citacion(citacion)
        if campo.CA_CCODIGO == 'ING_TELEFONO_CONDUCTOR':
            valor_default = normalizar_celular_conductor_visible(valor_default)

        campos.append({
            'id': campo.id,
            'codigo': campo.CA_CCODIGO,
            'name': f'{etapa.ET_CCODIGO.replace(" ", "")}_{campo.id}',
            'label': detalle.DET_CETIQUETAETAPA or campo.CA_CETIQUETA,
            'type': campo.CA_CTIPO.lower(),
            'default': valor_default,
            'required': detalle.DET_BOBLIGATORIO or campo.CA_BOBLIGATORIO,
            'maxlength': campo.CA_NLARGO,
            'datos': datos,
            'has_file': bool(dato_operacion and campo.CA_CTIPO.lower() == 'archivo'),
            'download_url': reverse('cit_download_file', args=[dato_operacion.id]) if dato_operacion and campo.CA_CTIPO.lower() == 'archivo' else '',
        })

    return campos


def guardar_operacion_etapa(citacion, request):
    empresa = citacion.EP_NID
    secuencia = citacion.SC_NID
    etapa_actual = citacion.ETAPA_ACTUAL
    detalle_secuencia_actual = DETALLE_SECUENCIA.objects.filter(
        SC_NID=secuencia,
        ET_NID=etapa_actual,
        SE_BHABILITADO=True
    ).first()

    if not detalle_secuencia_actual:
        raise Exception('La etapa actual no esta habilitada en la secuencia.')
    devolucion_guardia = obtener_devolucion_guardia_pendiente(citacion)
    if (not devolucion_guardia and detalle_secuencia_actual.SE_NPASO > 1) or citacion.CI_CESTADO == CIT_TERMINADO:
        raise Exception('El ingreso de camion ya fue enviado a la siguiente etapa.')
    if not devolucion_guardia and SYSLOGGER.objects.filter(LOG_COPERACION='AVANZA_AR', LOG_CADD1=str(citacion.id)).exists():
        raise Exception('El ingreso de camion ya fue enviado al Asistente de recepcion.')

    tuvo_datos_previos = DATO_OPERACION.objects.filter(
        CI_NID=citacion,
        SC_NID=secuencia,
        ET_NID=etapa_actual
    ).exists()

    if citacion.CI_CESTADO != CIT_EN_PROCESO:
        citacion.CI_CESTADO = CIT_EN_PROCESO
        citacion.CI_FFECHAINICIO = citacion.CI_FFECHAINICIO or datetime.now()
        citacion.save(update_fields=['CI_CESTADO', 'CI_FFECHAINICIO'])

    etapa_log_ingreso, _ = ETAPA_LOG.objects.get_or_create(
        CI_NID=citacion,
        EP_NID=empresa,
        SC_NID=secuencia,
        ET_NID=etapa_actual,
        EL_FFECHAFIN=None,
        defaults={
            'EL_FFECHAINICIO': datetime.now(),
            'US_INICIO_ID': request.user,
            'EL_CACCION': 'INGRESO_CAMION',
        }
    )
    if etapa_log_ingreso.US_INICIO_ID_id is None:
        etapa_log_ingreso.US_INICIO_ID = request.user
        etapa_log_ingreso.EL_CACCION = etapa_log_ingreso.EL_CACCION or 'INGRESO_CAMION'
        etapa_log_ingreso.save(update_fields=['US_INICIO_ID', 'EL_CACCION'])

    campos_etapa = obtener_campos_operacion_etapa(citacion, etapa_actual, request.user)

    for campo_data in campos_etapa:
        campo = CAMPO.objects.get(id=campo_data['id'])
        input_name = campo_data['name']
        tipo_documento_expediente = None
        nombre_archivo_expediente = None

        if campo.CA_CTIPO.lower() == 'archivo':
            archivo = request.FILES.get(input_name)
            if not archivo:
                if campo_data['required'] and not campo_data['has_file']:
                    raise Exception(f'Debe cargar el archivo {campo_data["label"]}.')
                continue
            tipo_documento_expediente = EXPEDIENTE_CAMPO_TIPO.get(campo.CA_CCODIGO)
            if tipo_documento_expediente:
                valor_campo, nombre_archivo_expediente = guardar_archivo_expediente_citacion(
                    citacion,
                    tipo_documento_expediente,
                    archivo
                )
            else:
                valor_campo = guardar_archivo_dato_operacion(citacion, etapa_actual, archivo)
        else:
            valor_campo = request.POST.get(input_name)
            if campo.CA_CTIPO == 'CHECK' and valor_campo is None:
                valor_campo = False
            if campo_data['required'] and (valor_campo is None or str(valor_campo).strip() == ''):
                raise Exception(f'Debe completar {campo_data["label"]}.')
            if campo.CA_CCODIGO == 'ING_TELEFONO_CONDUCTOR':
                valor_campo = normalize_chilean_mobile(valor_campo)

        if campo.CA_CCODIGO == 'CI_CNUMERODOCUMENTO':
            citacion.CI_CNUMERODOCUMENTO = valor_campo
            if not citacion.CI_CTIPODOCUMENTO:
                citacion.CI_CTIPODOCUMENTO = 'GUIA'
            citacion.save(update_fields=['CI_CNUMERODOCUMENTO', 'CI_CTIPODOCUMENTO'])
        elif campo.CA_BASIGNARVALOR and campo.CA_CCODIGO:
            setattr(citacion, campo.CA_CCODIGO, valor_campo)
            citacion.save(update_fields=[campo.CA_CCODIGO])

        dato_operacion, _ = DATO_OPERACION.objects.update_or_create(
            CI_NID=citacion,
            SC_NID=secuencia,
            ET_NID=etapa_actual,
            CAMP_NID=campo,
            defaults={
                'EP_NID': empresa,
                'US_NID': request.user,
                'DO_CVALOR': valor_campo,
                'DO_FFECHAREGISTRO': datetime.now(),
            }
        )
        if tipo_documento_expediente:
            registrar_documento_expediente(
                citacion,
                tipo_documento_expediente,
                valor_campo,
                nombre_archivo_expediente or os.path.basename(valor_campo),
                request.user,
                dato_operacion=dato_operacion
            )

    registrar_log_camion_no_planificado(
        request.user,
        empresa,
        'CORRIGE_DEV_GUA' if devolucion_guardia else 'ING_CAMION',
        (
            f'Correccion ingreso camion citacion #{citacion.id} por devolucion de Asistente Recepcion. '
            f'Motivo devolucion: {devolucion_guardia.get("observacion", "")}'
            if devolucion_guardia
            else f'{"Edicion" if tuvo_datos_previos else "Registro"} ingreso camion citacion #{citacion.id} etapa {etapa_actual.ET_CCODIGO}'
        ),
        citacion.id,
        etapa_actual.ET_CCODIGO
    )

    return tuvo_datos_previos


def asegurar_flujos_recepcion_etapa_0(empresa_id, usuario):
    flujos = []
    usuario_registro = usuario if getattr(usuario, 'is_authenticated', False) else None

    for codigo, nombre, nombre_base in FLUJOS_RECEPCION_ETAPA_0:
        secuencia = SECUENCIA.objects.filter(
            EP_NID_id=empresa_id
        ).filter(
            Q(SE_CCODIGO=codigo) | Q(SE_CNOMBRE=nombre)
        ).order_by('id').first()

        if not secuencia:
            secuencia = SECUENCIA.objects.create(
                EP_NID_id=empresa_id,
                US_NID=usuario_registro,
                SE_CTIPO='RECEPCION',
                SE_CCODIGO=codigo,
                SE_CNOMBRE=nombre,
                SE_BHABILITADO=True,
                SE_FFECHAREGISTRO=timezone.now(),
            )

        campos_actualizar = []

        if secuencia.SE_CCODIGO != codigo:
            secuencia.SE_CCODIGO = codigo
            campos_actualizar.append('SE_CCODIGO')

        if secuencia.SE_CTIPO != 'RECEPCION':
            secuencia.SE_CTIPO = 'RECEPCION'
            campos_actualizar.append('SE_CTIPO')

        if secuencia.SE_CNOMBRE != nombre:
            secuencia.SE_CNOMBRE = nombre
            campos_actualizar.append('SE_CNOMBRE')

        if not secuencia.SE_BHABILITADO:
            secuencia.SE_BHABILITADO = True
            campos_actualizar.append('SE_BHABILITADO')

        if usuario_registro and not secuencia.US_NID_id:
            secuencia.US_NID = usuario_registro
            campos_actualizar.append('US_NID')

        if not secuencia.SE_FFECHAREGISTRO:
            secuencia.SE_FFECHAREGISTRO = timezone.now()
            campos_actualizar.append('SE_FFECHAREGISTRO')

        if campos_actualizar:
            secuencia.save(update_fields=campos_actualizar)

        if not DETALLE_SECUENCIA.objects.filter(SC_NID=secuencia, SE_BHABILITADO=True).exists():
            secuencia_base = SECUENCIA.objects.filter(
                SE_CNOMBRE=nombre_base,
                SE_BHABILITADO=True
            ).exclude(
                pk=secuencia.pk
            ).order_by('EP_NID_id', 'id').first()

            if secuencia_base:
                detalles_base = DETALLE_SECUENCIA.objects.filter(
                    SC_NID=secuencia_base,
                    SE_BHABILITADO=True
                ).order_by('SE_NPASO', 'id')

                detalles_nuevos = [
                    DETALLE_SECUENCIA(
                        US_NID=detalle.US_NID,
                        USERS_RESPONSABLE_ID=detalle.USERS_RESPONSABLE_ID,
                        EP_NID_id=empresa_id,
                        SC_NID=secuencia,
                        ET_NID=detalle.ET_NID,
                        SE_NPASO=detalle.SE_NPASO,
                        SE_BHABILITADO=detalle.SE_BHABILITADO,
                        SE_BOBLIGATORIO=detalle.SE_BOBLIGATORIO,
                    )
                    for detalle in detalles_base
                ]

                if detalles_nuevos:
                    DETALLE_SECUENCIA.objects.bulk_create(detalles_nuevos)

        flujos.append(secuencia)

    return flujos


def codigo_etapa_despacho(nombre):
    texto = unicodedata.normalize('NFKD', str(nombre or '').strip().upper())
    texto = ''.join(caracter for caracter in texto if not unicodedata.combining(caracter))
    texto = re.sub(r'[^A-Z0-9]+', '_', texto).strip('_')
    return texto[:128] or 'ETAPA_DESPACHO'


def obtener_o_crear_etapa_despacho(empresa_id, usuario, nombre, paso):
    usuario_registro = usuario if getattr(usuario, 'is_authenticated', False) else None
    codigo = codigo_etapa_despacho(nombre)
    tipo_etapa = 'SALIDA' if nombre == 'Confirmar Salida' else 'OPERACION'

    etapa = ETAPA.objects.filter(
        EP_NID_id=empresa_id,
        ET_CCODIGO=codigo,
    ).order_by('id').first()

    if not etapa:
        etapa = ETAPA.objects.create(
            EP_NID_id=empresa_id,
            US_NID=usuario_registro,
            ET_CTIPO=tipo_etapa,
            ET_CCODIGO=codigo,
            ET_CNOMBRE=nombre,
            ET_CDESCRIPCION=f'Etapa operacional de despacho: {nombre}',
            ET_FFECHAREGISTRO=timezone.now(),
            ET_NCANTIDADMAXIMA=1,
            ET_TTIEMPOMAXIMO=time(0, 0),
            ET_TTIEMPOMINIMO=time(0, 0),
            ET_BHABILITADO=True,
        )
        return etapa

    campos_actualizar = []

    if etapa.ET_CNOMBRE != nombre:
        etapa.ET_CNOMBRE = nombre
        campos_actualizar.append('ET_CNOMBRE')

    if etapa.ET_CTIPO != tipo_etapa:
        etapa.ET_CTIPO = tipo_etapa
        campos_actualizar.append('ET_CTIPO')

    if not etapa.ET_BHABILITADO:
        etapa.ET_BHABILITADO = True
        campos_actualizar.append('ET_BHABILITADO')

    if etapa.ET_NCANTIDADMAXIMA in [None, 0]:
        etapa.ET_NCANTIDADMAXIMA = 1
        campos_actualizar.append('ET_NCANTIDADMAXIMA')

    if not etapa.ET_TTIEMPOMAXIMO:
        etapa.ET_TTIEMPOMAXIMO = time(0, 0)
        campos_actualizar.append('ET_TTIEMPOMAXIMO')

    if not etapa.ET_TTIEMPOMINIMO:
        etapa.ET_TTIEMPOMINIMO = time(0, 0)
        campos_actualizar.append('ET_TTIEMPOMINIMO')

    if usuario_registro and not etapa.US_NID_id:
        etapa.US_NID = usuario_registro
        campos_actualizar.append('US_NID')

    if not etapa.ET_FFECHAREGISTRO:
        etapa.ET_FFECHAREGISTRO = timezone.now()
        campos_actualizar.append('ET_FFECHAREGISTRO')

    if campos_actualizar:
        etapa.save(update_fields=campos_actualizar)

    return etapa


def asegurar_flujos_despacho_etapa_0(empresa_id, usuario):
    flujos = []
    usuario_registro = usuario if getattr(usuario, 'is_authenticated', False) else None

    for codigo, nombre, etapas in FLUJOS_DESPACHO_ETAPA_0:
        secuencia = SECUENCIA.objects.filter(
            EP_NID_id=empresa_id
        ).filter(
            Q(SE_CCODIGO=codigo) | Q(SE_CNOMBRE=nombre)
        ).order_by('id').first()

        if not secuencia:
            secuencia = SECUENCIA.objects.create(
                EP_NID_id=empresa_id,
                US_NID=usuario_registro,
                SE_CTIPO='DESPACHO',
                SE_CCODIGO=codigo,
                SE_CNOMBRE=nombre,
                SE_BHABILITADO=True,
                SE_FFECHAREGISTRO=timezone.now(),
            )

        campos_actualizar = []

        if secuencia.SE_CCODIGO != codigo:
            secuencia.SE_CCODIGO = codigo
            campos_actualizar.append('SE_CCODIGO')

        if secuencia.SE_CTIPO != 'DESPACHO':
            secuencia.SE_CTIPO = 'DESPACHO'
            campos_actualizar.append('SE_CTIPO')

        if secuencia.SE_CNOMBRE != nombre:
            secuencia.SE_CNOMBRE = nombre
            campos_actualizar.append('SE_CNOMBRE')

        if not secuencia.SE_BHABILITADO:
            secuencia.SE_BHABILITADO = True
            campos_actualizar.append('SE_BHABILITADO')

        if usuario_registro and not secuencia.US_NID_id:
            secuencia.US_NID = usuario_registro
            campos_actualizar.append('US_NID')

        if not secuencia.SE_FFECHAREGISTRO:
            secuencia.SE_FFECHAREGISTRO = timezone.now()
            campos_actualizar.append('SE_FFECHAREGISTRO')

        if campos_actualizar:
            secuencia.save(update_fields=campos_actualizar)

        etapas_esperadas_ids = set()

        for paso, nombre_etapa in enumerate(etapas, start=1):
            etapa = obtener_o_crear_etapa_despacho(empresa_id, usuario, nombre_etapa, paso)
            etapas_esperadas_ids.add(etapa.id)
            detalle = DETALLE_SECUENCIA.objects.filter(
                EP_NID_id=empresa_id,
                SC_NID=secuencia,
                ET_NID=etapa,
            ).order_by('id').first()

            if not detalle:
                DETALLE_SECUENCIA.objects.create(
                    EP_NID_id=empresa_id,
                    US_NID=usuario_registro,
                    SC_NID=secuencia,
                    ET_NID=etapa,
                    SE_NPASO=paso,
                    SE_BHABILITADO=True,
                    SE_BOBLIGATORIO=True,
                )
                continue

            campos_detalle = []

            if detalle.SE_NPASO != paso:
                detalle.SE_NPASO = paso
                campos_detalle.append('SE_NPASO')

            if not detalle.SE_BHABILITADO:
                detalle.SE_BHABILITADO = True
                campos_detalle.append('SE_BHABILITADO')

            if not detalle.SE_BOBLIGATORIO:
                detalle.SE_BOBLIGATORIO = True
                campos_detalle.append('SE_BOBLIGATORIO')

            if usuario_registro and not detalle.US_NID_id:
                detalle.US_NID = usuario_registro
                campos_detalle.append('US_NID')

            if campos_detalle:
                detalle.save(update_fields=campos_detalle)

        DETALLE_SECUENCIA.objects.filter(
            EP_NID_id=empresa_id,
            SC_NID=secuencia,
            SE_BHABILITADO=True
        ).exclude(
            ET_NID_id__in=etapas_esperadas_ids
        ).update(SE_BHABILITADO=False, SE_FFECHAELIMICACION=timezone.now())

        flujos.append(secuencia)

    return flujos


def PLANIFICACION_ADDONE(request):
    try:
        if usuario_es_ingreso_camion(request.user):
            messages.error(request, 'Su perfil puede ingresar camiones, pero no crear planificaciones.')
            return redirect('/pla_listall/')

        if request.user.is_superuser == False:
            usuario = request.user.id
            if not usuario_es_planificador(request.user) and not validar_perfiles_activos(usuario, "pla_addone"):
                messages.error(request, 'No tiene permisos para acceder a esta sección')
                return redirect('/')

        Empresa = Verificar_empresa(request)

        if Empresa is None:
            return redirect('/seleccionar_empresa/')

        tipo_planificacion = str(request.GET.get('tipo') or '').strip().upper()
        if tipo_planificacion not in ['RECEPCION', 'DESPACHO']:
            tipo_planificacion = ''

        solicitud_patio_inicial = None
        solicitud_patio_id = str(
            request.GET.get('solicitud_no_planificado_id')
            or request.POST.get('solicitud_no_planificado_id')
            or ''
        ).strip()
        if solicitud_patio_id and usuario_puede_revisar_no_planificado_patio(request.user):
            solicitud_patio_inicial = CAMION_PATIO_NO_PLANIFICADO.objects.select_related(
                'CPA_NID'
            ).filter(
                pk=solicitud_patio_id,
                EP_NID_id=Empresa,
                CPNP_CESTADO=CAMION_PATIO_NO_PLANIFICADO.ESTADO_APROBADO_PENDIENTE_PLANIFICACION,
                PL_NID__isnull=True
            ).first()

        if request.method == 'POST':
            form = formPLANIFICACION(request.POST)

            if form.is_valid():
                form.instance.US_NID = request.user
                form.instance.EP_NID_id = Empresa
                form.instance.PL_FFECHAREGISTRO = datetime.now()
                planificacion = form.save()

                messages.success(request, 'Planificación creada correctamente')
                return redirect(f'/pla_listone/{planificacion.pk}')
            else:
                messages.error(request, f'Error en el formulario, {str(form.errors)}')
                return redirect('/pla_addone/')

        form = formPLANIFICACION()

        avisos_desarrollo = []

        try:
            clientes_sap = obtener_clientes_aceite(Empresa)
        except Exception as e:
            print(f'PLANIFICACION_ADDONE clientes_sap no disponibles: {e}')
            clientes_sap = []
            avisos_desarrollo.append('Clientes SAP no disponibles. El modal se muestra con el selector vacio.')

        proveedores_sap = []

        try:
            secuencias_recepcion = asegurar_flujos_recepcion_etapa_0(Empresa, request.user)
            asegurar_flujos_despacho_etapa_0(Empresa, request.user)
            secuencias_despacho = list(SECUENCIA.objects.filter(
                EP_NID_id=Empresa,
                SE_CTIPO='DESPACHO',
                SE_BHABILITADO=True
            ).order_by("SE_CNOMBRE"))
            secuencias = secuencias_recepcion + secuencias_despacho
        except Exception as e:
            print(f'PLANIFICACION_ADDONE secuencias no disponibles: {e}')
            secuencias = []
            avisos_desarrollo.append('Secuencias no disponibles. El modal se muestra con el selector vacio.')

        ctx = {
            'form': form,
            'clientes_sap': clientes_sap,
            'proveedores_sap': proveedores_sap,
            'secuencias': secuencias,
            'abrir_modal': request.GET.get('modal', ''),
            'avisos_desarrollo': avisos_desarrollo,
            'empresa_id': Empresa,
            'tipo_planificacion': tipo_planificacion,
            'tipo_planificacion_label': {
                'RECEPCION': 'Recepción',
                'DESPACHO': 'Despacho',
            }.get(tipo_planificacion, ''),
            'solicitud_no_planificado_id': solicitud_patio_inicial.id if solicitud_patio_inicial else '',
            'camion_patio_inicial': ({
                'patente': solicitud_patio_inicial.CPA_NID.CPA_CPATENTE or '',
                'proveedor': solicitud_patio_inicial.CPA_NID.CPA_CPROVEEDOR_DECLARADO or '',
                'cliente': solicitud_patio_inicial.CPA_NID.CPA_CCLIENTE_DECLARADO or '',
                'insumo': solicitud_patio_inicial.CPA_NID.CPA_CINSUMO_DECLARADO_GUIA or '',
                'guia': solicitud_patio_inicial.CPA_NID.CPA_CNUMERO_GUIA or '',
                'bl': solicitud_patio_inicial.CPA_NID.CPA_CBL or '',
                'observacion': solicitud_patio_inicial.CPA_NID.CPA_COBSERVACION or '',
                'fecha_llegada': timezone.localtime(solicitud_patio_inicial.CPA_NID.CPA_FFECHALLEGADA).strftime('%Y-%m-%d'),
                'camion_patio_id': solicitud_patio_inicial.CPA_NID_id,
            } if solicitud_patio_inicial else {}),
        }

        return render(request, 'home/PLANIFICACION/pla_addone.html', ctx)

    except Exception as e:
        print(e)
        messages.error(request, f'Error, {str(e)}')
        return redirect('/pla_listall/')

