        form.fields['SN_NID'].choices = listarOpcionesTabla('CAST("id" AS text)', ''' "SN_CRUT" || ' - ' || "SN_CRAZONSOCIAL" ''', 'SOCIONEGOCIO', '', '', '''"SN_CTIPO" = 'S' AND "SN_BHABILITADO" = TRUE ''')
