def ajax_operacion_planta_descargar_documento_calidad(request):
    citacion_id = request.GET.get('citacion_id')
    if not citacion_id:
        return JsonResponse({'success': False, 'message': 'Debe indicar citacion.'}, status=400)

    Empresa = Verificar_empresa(request)
    if Empresa is None:
        return JsonResponse({'success': False, 'message': 'Debe seleccionar una empresa.'}, status=400)

    try:
        citacion = CITACION.objects.get(pk=citacion_id, EP_NID_id=Empresa, CI_BHABILITADO=True)
    except CITACION.DoesNotExist:
        return JsonResponse({'success': False, 'message': 'Citacion no encontrada.'}, status=404)

    if not usuario_es_operacion_planta(request.user):
        return JsonResponse({'success': False, 'message': 'No tiene permisos para descargar este documento.'}, status=403)

    metadata = _leer_metadata_resultado_calidad(citacion)
    ruta = metadata.get('documento_ruta') if metadata else ''
    nombre = metadata.get('documento_nombre') if metadata else ''
    if not ruta or not nombre or not os.path.isfile(ruta) or not _ruta_ticket_permitida(ruta):
        return JsonResponse({'success': False, 'message': 'Documento de calidad no disponible.'}, status=404)

    return FileResponse(
        open(ruta, 'rb'),
        as_attachment=False,
        filename=nombre,
        content_type='application/octet-stream'
    )


def _validar_operacion_planta_ticket_request(request, citacion_id, paso_nombre):
    if not usuario_es_operacion_planta(request.user):
        return None, None, JsonResponse({'valid': False, 'msg': 'No tiene permisos para Operacion Planta.'}, status=403)

    Empresa = Verificar_empresa(request)
    if Empresa is None:
        return None, None, JsonResponse({'valid': False, 'msg': 'Debe seleccionar una empresa.'}, status=400)

    try:
        citacion = CITACION.objects.select_related('EP_NID', 'PL_NID', 'SC_NID', 'CA_NID').get(
            pk=citacion_id,
            EP_NID_id=Empresa,
            CI_BHABILITADO=True
        )
    except CITACION.DoesNotExist:
        return None, None, JsonResponse({'valid': False, 'msg': 'Citacion no encontrada.'}, status=404)

    tipo_ticket = _tipo_ticket_pesaje(paso_nombre)
    if not tipo_ticket:
        return None, None, JsonResponse({'valid': False, 'msg': 'El paso indicado no requiere ticket de pesaje.'}, status=400)

    _, pasos_config = obtener_pasos_operacion_citacion(citacion)
    responsables_paso = None
    for nombre_paso, responsables in pasos_config:
        if nombre_paso == paso_nombre:
            responsables_paso = responsables
            break

    if not responsables_paso:
        return None, None, JsonResponse({'valid': False, 'msg': 'Paso operacional no valido.'}, status=400)
    if not usuario_puede_paso_operacion(request.user, responsables_paso):
        return None, None, JsonResponse({'valid': False, 'msg': f'Solo lectura: este paso corresponde a {" / ".join(responsables_paso)}'}, status=403)

    logs_completados = set(OPERACION_PLANTA_LOG.objects.filter(
        CI_NID=citacion,
        OPL_CESTADO=OPERACION_PLANTA_LOG.ESTADO_COMPLETADO
    ).values_list('OPL_CPASO', flat=True))
    paso_actual_visible = resolver_estado_operacional_visible(citacion, pasos_config, logs_completados)
    if paso_nombre != paso_actual_visible:
        return None, None, JsonResponse({'valid': False, 'msg': f'Solo puede operar la etapa activa actual: {paso_actual_visible}.'}, status=409)

    return citacion, tipo_ticket, None


def ajax_operacion_planta_obtener_ticket_pesaje(request):
    if request.method != 'GET':
        return JsonResponse({'valid': False, 'msg': 'Metodo no permitido.'}, status=405)

    citacion_id = request.GET.get('citacion_id')
    paso_nombre = str(request.GET.get('paso_codigo') or request.GET.get('paso_nombre') or '').strip()
    if not citacion_id or not paso_nombre:
        return JsonResponse({'valid': False, 'msg': 'Debe indicar citacion y paso operacional.'}, status=400)

    citacion, tipo_ticket, error_response = _validar_operacion_planta_ticket_request(request, citacion_id, paso_nombre)
    if error_response:
        return error_response

    valores_ingreso = obtener_valores_ingreso_camion(citacion)
    patente = valores_ingreso.get('patente') or (citacion.CA_NID.CAM_CPATENTE if citacion.CA_NID else '')
    patente_normalizada = _normalizar_patente(patente)
    _debug_ticket_pesaje(
        'Patente obtenida para ticket',
        citacion_id=citacion.id,
        paso=paso_nombre,
        tipo_ticket=tipo_ticket,
        patente_original=repr(patente),
        patente_normalizada=patente_normalizada
    )
    if not patente_normalizada:
        return JsonResponse({'valid': False, 'msg': 'La citacion no tiene patente para buscar ticket de pesaje.'}, status=400)

    try:
        ruta_pdf = _buscar_ticket_pesaje_mas_reciente(patente_normalizada, tipo_ticket)
        if not ruta_pdf:
            return JsonResponse({'valid': False, 'msg': f'No se encontro ticket COM_{tipo_ticket} para la patente {patente_normalizada}.'}, status=404)

        datos_ticket = _extraer_datos_ticket_pesaje(ruta_pdf, tipo_ticket)
        ruta_local = _copiar_ticket_local_si_necesario(ruta_pdf)
        if not _ruta_ticket_permitida(ruta_local):
            return JsonResponse({'valid': False, 'msg': 'La ruta local del ticket no esta permitida.'}, status=400)

        campo = _obtener_campo_ticket_pesaje(citacion, tipo_ticket, request.user)
        metadata = _metadata_ticket_pesaje(
            citacion,
            paso_nombre,
            tipo_ticket,
            patente_normalizada,
            ruta_local,
            datos_ticket,
            request.user
        )
        dato, _ = DATO_OPERACION.objects.update_or_create(
            CI_NID=citacion,
            SC_NID=citacion.SC_NID,
            ET_NID=citacion.ETAPA_ACTUAL,
            CAMP_NID=campo,
            defaults={
                'EP_NID': citacion.EP_NID,
                'US_NID': request.user,
                'DO_CVALOR': json.dumps(metadata, ensure_ascii=False),
                'DO_NPESO': int(datos_ticket['peso_neto']),
                'DO_FFECHAREGISTRO': timezone.now(),
            }
        )

        registrar_log_camion_no_planificado(
            request.user,
            citacion.EP_NID,
            f'TICKET_PESAJE_{tipo_ticket}',
            f'Ticket {tipo_ticket} congelado para citacion #{citacion.id}. Folio: {datos_ticket["folio"]}. Peso: {datos_ticket["peso_neto"]}.',
            citacion.id,
            os.path.basename(ruta_local)
        )

        payload = _payload_ticket_pesaje_guardado(citacion, paso_nombre, request) or {}
        return JsonResponse({
            'valid': True,
            'guardado': True,
            'dato_id': dato.id,
            'peso_neto': datos_ticket['peso_neto'],
            'folio': datos_ticket['folio'],
            'observacion': datos_ticket.get('observacion') or '',
            'download_url': payload.get('download_url', ''),
            'nombre_archivo_pdf': payload.get('nombre_archivo_pdf', os.path.basename(ruta_local)),
        })
    except ValueError as e:
        return JsonResponse({'valid': False, 'msg': str(e)}, status=400)
    except Exception as e:
        return JsonResponse({'valid': False, 'msg': f'Error al obtener ticket de pesaje: {str(e)}'}, status=500)


def ajax_operacion_planta_descargar_ticket_pesaje(request):
    dato_id = request.GET.get('dato_id')
    if not dato_id:
        return JsonResponse({'valid': False, 'msg': 'Debe indicar el dato del ticket.'}, status=400)

    Empresa = Verificar_empresa(request)
    if Empresa is None:
        return JsonResponse({'valid': False, 'msg': 'Debe seleccionar una empresa.'}, status=400)

    try:
        dato = DATO_OPERACION.objects.select_related('CI_NID', 'CAMP_NID').get(
            pk=dato_id,
            EP_NID_id=Empresa,
            CAMP_NID__CA_CCODIGO__in=[
                _codigo_campo_ticket_pesaje('ENT'),
                _codigo_campo_ticket_pesaje('SAL'),
            ]
        )
    except DATO_OPERACION.DoesNotExist:
        return JsonResponse({'valid': False, 'msg': 'Ticket no encontrado.'}, status=404)

    if not usuario_es_operacion_planta(request.user):
        return JsonResponse({'valid': False, 'msg': 'No tiene permisos para descargar este ticket.'}, status=403)

    metadata = _leer_metadata_ticket_dato(dato)
    ruta_pdf = metadata.get('ruta_real_pdf') if metadata else ''
    if not ruta_pdf or not os.path.isfile(ruta_pdf) or not _ruta_ticket_permitida(ruta_pdf):
        return JsonResponse({'valid': False, 'msg': 'El PDF congelado no existe o no esta permitido.'}, status=404)

    return FileResponse(
        open(ruta_pdf, 'rb'),
        as_attachment=True,
        filename=os.path.basename(ruta_pdf),
        content_type='application/pdf'
    )


def formatear_duracion_planta(fecha_inicio):
    if not fecha_inicio:
        return 'No disponible'

    delta = timezone.now() - fecha_inicio
    total_minutos = max(int(delta.total_seconds() // 60), 0)
    horas = total_minutos // 60
    minutos = total_minutos % 60

    if horas:
        return f'{horas}h {minutos}m'
    return f'{minutos}m'


def formatear_duracion_operacional(delta):
    if not delta:
        return 'No disponible'

    total_segundos = max(int(delta.total_seconds()), 0)
    dias = total_segundos // 86400
    horas = (total_segundos % 86400) // 3600
    minutos = (total_segundos % 3600) // 60
    segundos = total_segundos % 60

    if dias:
        return f'{dias}d {horas}h {minutos}m'
    if horas:
        return f'{horas}h {minutos:02d}m {segundos:02d}s'
    if minutos:
        return f'{minutos} min {segundos:02d} seg'
    return f'{segundos} seg'


LOG_AUTORIZA_SALIDA_PLANTA = 'AUTORIZA_SALIDA_PLANTA'
LOG_AUTORIZA_INGRESO_PLANTA_OP = 'AUTORIZA_REING_PLANTA'


def es_despacho_bodega_externa_operacion(citacion):
    if not citacion or not es_citacion_despacho(citacion):
        return False
    codigo = str(citacion.SC_NID.SE_CCODIGO if citacion.SC_NID else '').strip().upper()
    nombre = normalizar_nombre_flujo_operacion(citacion.SC_NID.SE_CNOMBRE if citacion.SC_NID else '')
    return codigo == 'BODEGA_EXTERNA_CLIENTE' or 'DESPACHO DESDE BODEGA EXTERNA' in nombre


def formatear_duracion_hms(delta):
    if not delta:
        return '00:00:00'
    total_segundos = max(int(delta.total_seconds()), 0)
    horas = total_segundos // 3600
    minutos = (total_segundos % 3600) // 60
    segundos = total_segundos % 60
    return f'{horas:02d}:{minutos:02d}:{segundos:02d}'


def _fecha_operacion_iso(fecha):
    return timezone.localtime(fecha).isoformat() if fecha else ''


def _fecha_operacion_ms(fecha):
    return int(timezone.localtime(fecha).timestamp() * 1000) if fecha else ''


def _fecha_operacion_legible(fecha):
    return timezone.localtime(fecha).strftime('%d/%m/%Y %H:%M') if fecha else ''


def _ultimo_log_operacion(citacion, paso):
    return OPERACION_PLANTA_LOG.objects.select_related('US_NID').filter(
        CI_NID=citacion,
        OPL_CPASO=paso,
        OPL_CESTADO=OPERACION_PLANTA_LOG.ESTADO_COMPLETADO
    ).order_by('-OPL_FFECHAREGISTRO').first()


def _resumen_sap_despacho_bodega_externa(citacion):
    detalle_operacional = detalle_operacional_dict(citacion)
    detalle_despacho = detalle_despacho_resumen_dict(citacion, detalle_operacional)
    valores_ingreso = obtener_valores_ingreso_camion(citacion)

    def primero(*valores):
        for valor in valores:
            if valor not in [None, '']:
                texto = str(valor).strip()
                if texto:
                    return texto
        return ''

    datos = {
        'cliente_codigo': primero(detalle_despacho.get('sap_cliente_codigo')),
        'cliente_nombre': primero(detalle_despacho.get('sap_cliente_nombre'), citacion.SN_NID.SN_CRAZONSOCIAL if citacion.SN_NID else ''),
        'oc_cliente': primero(detalle_despacho.get('sap_oc_cliente'), detalle_despacho.get('oc_cliente'), detalle_operacional.get('pedido')),
        'sap_numero_acuerdo': primero(detalle_despacho.get('sap_numero_acuerdo')),
        'sap_abs_id': primero(detalle_despacho.get('sap_abs_id')),
        'sap_linea_acuerdo': primero(detalle_despacho.get('sap_linea_acuerdo')),
        'sap_codigo_producto': primero(detalle_despacho.get('sap_codigo_producto'), detalle_operacional.get('codigo')),
        'sap_nombre_producto': primero(detalle_despacho.get('sap_nombre_producto'), detalle_operacional.get('insumo')),
        'sap_cantidad_planificada': primero(detalle_despacho.get('sap_cantidad_planificada')),
        'sap_cantidad_consumida': primero(detalle_despacho.get('sap_cantidad_consumida')),
        'sap_saldo_contrato': primero(detalle_despacho.get('sap_saldo_contrato'), detalle_operacional.get('cantidad_disponible')),
        'cantidad_intentada': primero(detalle_despacho.get('cantidad_intentada_despachar')),
        'patente': primero(valores_ingreso.get('patente'), detalle_despacho.get('patente')),
        'conductor': primero(valores_ingreso.get('conductor'), detalle_despacho.get('conductor')),
        'transportista': primero(valores_ingreso.get('transportista'), detalle_despacho.get('empresa_transporte')),
        'bodega_condicion': primero(detalle_despacho.get('bodega'), detalle_despacho.get('condicion_entrega'), detalle_operacional.get('estanque_destino')),
    }

    for key, value in list(datos.items()):
        datos[key] = texto_sin_informacion(value)

    campos_completos = [
        {'label': 'Cliente SAP / CardCode', 'value': datos['cliente_codigo']},
        {'label': 'Cliente SAP / CardName', 'value': datos['cliente_nombre']},
        {'label': 'OC cliente / NumAtCard', 'value': datos['oc_cliente']},
        {'label': 'Numero acuerdo SAP visible', 'value': datos['sap_numero_acuerdo']},
        {'label': 'SAP AbsID', 'value': datos['sap_abs_id']},
        {'label': 'Linea acuerdo', 'value': datos['sap_linea_acuerdo']},
        {'label': 'Codigo producto SAP', 'value': datos['sap_codigo_producto']},
        {'label': 'Nombre producto SAP', 'value': datos['sap_nombre_producto']},
        {'label': 'Cantidad planificada', 'value': datos['sap_cantidad_planificada']},
        {'label': 'Cantidad consumida', 'value': datos['sap_cantidad_consumida']},
        {'label': 'Saldo contrato', 'value': datos['sap_saldo_contrato']},
        {'label': 'Cantidad intentada a despachar', 'value': datos['cantidad_intentada']},
        {'label': 'Patente', 'value': datos['patente']},
        {'label': 'Conductor', 'value': datos['conductor']},
        {'label': 'Transportista', 'value': datos['transportista']},
        {'label': 'Bodega / condicion entrega', 'value': datos['bodega_condicion']},
    ]
    secciones_autorizacion = [
        {
            'titulo': 'Datos SAP / Cliente',
            'campos': campos_completos[0:6],
        },
        {
            'titulo': 'Producto / Contrato',
            'campos': campos_completos[6:12],
        },
        {
            'titulo': 'Transporte',
            'campos': campos_completos[12:16],
        },
    ]
    campos_resumen = [
        {'label': 'Cliente', 'value': datos['cliente_nombre']},
        {'label': 'OC cliente', 'value': datos['oc_cliente']},
        {'label': 'Producto SAP', 'value': datos['sap_nombre_producto']},
        {'label': 'Codigo producto', 'value': datos['sap_codigo_producto']},
        {'label': 'Cantidad intentada', 'value': datos['cantidad_intentada']},
        {'label': 'Patente', 'value': datos['patente']},
        {'label': 'Conductor', 'value': datos['conductor']},
        {'label': 'Transportista', 'value': datos['transportista']},
    ]
    return {
        'datos': datos,
        'campos_completos': campos_completos,
        'secciones_autorizacion': secciones_autorizacion,
        'campos_resumen': campos_resumen,
    }


def _payload_tramo_salida_ingreso_bodega_externa(citacion):
    salida_log = _ultimo_log_operacion(citacion, PASO_AUTORIZACION_SALIDA_INICIAL)
    ingreso_log = _ultimo_log_operacion(citacion, PASO_INGRESO_PLANTA_DESPACHO)
    inicio = salida_log.OPL_FFECHAREGISTRO if salida_log else None
    fin = ingreso_log.OPL_FFECHAREGISTRO if ingreso_log else None
    referencia_fin = fin or timezone.now()
    delta = (referencia_fin - inicio) if inicio else None
    return {
        'iniciada': bool(inicio),
        'activa': bool(inicio and not fin),
        'finalizada': bool(inicio and fin),
        'inicio_iso': _fecha_operacion_iso(inicio),
        'inicio_ms': _fecha_operacion_ms(inicio),
        'inicio_legible': _fecha_operacion_legible(inicio),
        'fin_iso': _fecha_operacion_iso(fin),
        'fin_legible': _fecha_operacion_legible(fin),
        'duracion_legible': formatear_duracion_hms(delta) if delta else '00:00:00',
        'usuario_salida': getattr(salida_log.US_NID, 'username', '') if salida_log and salida_log.US_NID_id else '',
        'usuario_ingreso': getattr(ingreso_log.US_NID, 'username', '') if ingreso_log and ingreso_log.US_NID_id else '',
    }


def _payload_autorizacion_salida_bodega_externa(citacion):
    resumen = _resumen_sap_despacho_bodega_externa(citacion)
    log = _ultimo_log_operacion(citacion, PASO_AUTORIZACION_SALIDA_INICIAL)
    return {
        'registrada': bool(log),
        'campos': resumen['campos_completos'],
        'secciones': resumen['secciones_autorizacion'],
        'tramo': _payload_tramo_salida_ingreso_bodega_externa(citacion),
        'usuario': getattr(log.US_NID, 'username', '') if log and log.US_NID_id else '',
        'fecha_hora': _fecha_operacion_legible(log.OPL_FFECHAREGISTRO if log else None),
    }


def _payload_ingreso_planta_bodega_externa(citacion):
    resumen = _resumen_sap_despacho_bodega_externa(citacion)
    log = _ultimo_log_operacion(citacion, PASO_INGRESO_PLANTA_DESPACHO)
    return {
        'registrada': bool(log),
        'campos': resumen['campos_resumen'],
        'tramo': _payload_tramo_salida_ingreso_bodega_externa(citacion),
        'usuario': getattr(log.US_NID, 'username', '') if log and log.US_NID_id else '',
        'fecha_hora': _fecha_operacion_legible(log.OPL_FFECHAREGISTRO if log else None),
    }


def _registrar_syslog_operacion_planta(citacion, usuario, operacion, descripcion, add2=''):
    registrar_log_camion_no_planificado(
        usuario,
        citacion.EP_NID,
        operacion,
        descripcion,
        citacion.id,
        add2 or (citacion.SC_NID.SE_CCODIGO if citacion.SC_NID else '')
    )


def obtener_top_camiones_tiempo_planta(empresa_id, limite=3):
    logs_autorizacion = SYSLOGGER.objects.select_related('US_NID').filter(
        EP_NID_id=empresa_id,
        LOG_COPERACION='AUTORIZA_INGRESO_PLANTA'
    ).order_by('-LOG_FFECHAREGISTRO')

    autorizacion_por_citacion = {}
    for log in logs_autorizacion:
        citacion_id = str(log.LOG_CADD1 or '').strip()
        if citacion_id.isdigit() and citacion_id not in autorizacion_por_citacion:
            autorizacion_por_citacion[citacion_id] = log

    citacion_ids = [int(citacion_id) for citacion_id in autorizacion_por_citacion.keys()]
    if not citacion_ids:
        return []

    citaciones = CITACION.objects.select_related(
        'EP_NID', 'PL_NID', 'SC_NID', 'SN_NID', 'CA_NID'
    ).filter(
        id__in=citacion_ids,
        EP_NID_id=empresa_id,
        CI_BHABILITADO=True
    ).exclude(CI_CESTADO=CIT_RECHAZADO)

    citaciones_con_salida = set(OPERACION_PLANTA_LOG.objects.filter(
        CI_NID_id__in=citacion_ids,
        OPL_CPASO='Confirmar Salida',
        OPL_CESTADO=OPERACION_PLANTA_LOG.ESTADO_COMPLETADO
    ).values_list('CI_NID_id', flat=True))

    ranking = []
    for citacion in citaciones:
        if citacion.id in citaciones_con_salida:
            continue

        log_autorizacion = autorizacion_por_citacion.get(str(citacion.id))
        if not log_autorizacion or not log_autorizacion.LOG_FFECHAREGISTRO:
            continue

        logs_pasos = list(OPERACION_PLANTA_LOG.objects.filter(
            CI_NID=citacion
        ).order_by('OPL_FFECHAREGISTRO'))
        completados = {
            log.OPL_CPASO
            for log in logs_pasos
            if log.OPL_CESTADO == OPERACION_PLANTA_LOG.ESTADO_COMPLETADO
        }
        nombre_flujo, pasos_config = obtener_pasos_operacion_citacion(citacion)
        etapa_actual = resolver_estado_operacional_visible(citacion, pasos_config, completados)
        valores_ingreso = obtener_valores_ingreso_camion(citacion)

        ranking.append({
            'citacion': citacion,
            'patente': texto_sin_informacion(valores_ingreso.get('patente')),
            'conductor': texto_sin_informacion(valores_ingreso.get('conductor')),
            'estado_actual': etapa_actual,
            'nombre_flujo': nombre_flujo,
            'ingreso_autorizado': timezone.localtime(log_autorizacion.LOG_FFECHAREGISTRO).strftime('%d/%m/%Y %H:%M'),
            'tiempo_planta': formatear_duracion_planta(log_autorizacion.LOG_FFECHAREGISTRO),
            'minutos_planta': max(int((timezone.now() - log_autorizacion.LOG_FFECHAREGISTRO).total_seconds() // 60), 0),
        })

    ranking.sort(key=lambda item: item['minutos_planta'], reverse=True)
    return ranking[:limite]


def SEGUIMIENTO_OPERACIONAL(request):
    Empresa = Verificar_empresa(request)
    if Empresa is None:
        messages.error(request, 'Debe seleccionar una empresa.')
        return redirect('/')

    logs_autorizacion = SYSLOGGER.objects.select_related('US_NID').filter(
        EP_NID_id=Empresa,
        LOG_COPERACION='AUTORIZA_INGRESO_PLANTA'
    ).order_by('-LOG_FFECHAREGISTRO')

    autorizacion_por_citacion = {}
    for log in logs_autorizacion:
        citacion_id = str(log.LOG_CADD1 or '').strip()
        if citacion_id.isdigit() and citacion_id not in autorizacion_por_citacion:
            autorizacion_por_citacion[citacion_id] = log

    citacion_ids = [int(citacion_id) for citacion_id in autorizacion_por_citacion.keys()]
    citaciones = CITACION.objects.select_related(
        'EP_NID', 'PL_NID', 'SC_NID', 'SN_NID', 'CA_NID'
    ).filter(
        id__in=citacion_ids,
        EP_NID_id=Empresa,
        CI_BHABILITADO=True
    ).exclude(CI_CESTADO=CIT_RECHAZADO).order_by('-id')

    citacion_items = {
        item.CI_NID_id: item
        for item in CITACION_ITEM.objects.select_related('IT_NID').filter(CI_NID_id__in=citacion_ids)
    }

    rows = []
    for citacion in citaciones:
        logs_pasos = list(OPERACION_PLANTA_LOG.objects.select_related('US_NID').filter(
            CI_NID=citacion
        ).order_by('OPL_FFECHAREGISTRO'))
        completados = {log.OPL_CPASO for log in logs_pasos if log.OPL_CESTADO == OPERACION_PLANTA_LOG.ESTADO_COMPLETADO}

        if 'Confirmar Salida' in completados:
            continue

        nombre_flujo, pasos_config = obtener_pasos_operacion_citacion(citacion)
        nombres_pasos = [paso for paso, _ in pasos_config]
        etapa_actual = resolver_estado_operacional_visible(citacion, pasos_config, completados)
        accion_toma_muestra = _payload_toma_muestra_accion(citacion, nombre_flujo) if etapa_actual == PASO_TOMA_MUESTRA else None
        ciclo_descarga_actual = _payload_ciclo_descarga(citacion) if etapa_actual == PASO_CICLO_DESCARGA else None
        ultimo_log = logs_pasos[-1] if logs_pasos else None
        log_autorizacion = autorizacion_por_citacion.get(str(citacion.id))
        logs_operacionales_completados = [
            log for log in logs_pasos
            if log.OPL_CPASO in nombres_pasos and log.OPL_CESTADO == OPERACION_PLANTA_LOG.ESTADO_COMPLETADO
        ]
        inicio_etapa_actual = (
            logs_operacionales_completados[-1].OPL_FFECHAREGISTRO
            if logs_operacionales_completados
            else (log_autorizacion.LOG_FFECHAREGISTRO if log_autorizacion else None)
        )
        valores_ingreso = obtener_valores_ingreso_camion(citacion)
        item = citacion_items.get(citacion.id)
        tipo_citacion = str(citacion.CI_CTIPO or (citacion.PL_NID.PL_CTIPOCUPO if citacion.PL_NID else '') or '').upper()
        tipo_citacion_label = 'DESPACHO' if tipo_citacion == CIT_DESPACHO else 'RECEPCION'
        producto_generico = item.IT_NID.IT_CNOMBRE if item and item.IT_NID else 'Sin producto'
        detalle_operacional = detalle_operacional_dict(citacion)
        insumo_sap_planificado = obtener_insumo_sap_planificado(citacion, detalle_operacional).get('insumo')
        if tipo_citacion == CIT_DESPACHO:
            detalle_despacho = detalle_despacho_resumen_dict(citacion, detalle_operacional)
            nombre_producto_sap = detalle_despacho.get('sap_nombre_producto') or insumo_sap_planificado or producto_generico
        else:
            nombre_producto_sap = insumo_sap_planificado or producto_generico

        pasos = construir_estado_pasos_operacion(nombres_pasos, etapa_actual, completados)

        historial = []
        inicio_historial = log_autorizacion.LOG_FFECHAREGISTRO if log_autorizacion and log_autorizacion.LOG_FFECHAREGISTRO else None
        for log in logs_pasos:
            if log.OPL_CPASO == 'Habilitar Operacion Planta':
                continue
            fin_etapa = log.OPL_FFECHAREGISTRO
            duracion_etapa = (
                formatear_duracion_operacional(fin_etapa - inicio_historial)
                if inicio_historial and fin_etapa
                else 'No disponible'
            )
            historial.append({
                'paso': log.OPL_CPASO,
                'usuario': log.US_NID.username if log.US_NID else '',
                'responsable': log.OPL_CPERFIL_RESPONSABLE,
                'fecha': timezone.localtime(log.OPL_FFECHAREGISTRO).strftime('%d/%m/%Y %H:%M') if log.OPL_FFECHAREGISTRO else '',
                'duracion_etapa_legible': duracion_etapa,
                'estado': log.OPL_CESTADO,
                'observacion': log.OPL_COBSERVACION or '',
            })
            if fin_etapa:
                inicio_historial = fin_etapa

        rows.append({
            'citacion': citacion,
            'citacion_id': citacion.id,
            'patente': texto_sin_informacion(valores_ingreso.get('patente')),
            'conductor': texto_sin_informacion(valores_ingreso.get('conductor')),
            'producto': nombre_producto_sap,
            'tipo_citacion': tipo_citacion or 'RECEPCION',
            'tipo_citacion_label': tipo_citacion_label,
            'estado_actual': etapa_actual,
            'estado_accion_toma_muestra': accion_toma_muestra if accion_toma_muestra and accion_toma_muestra.get('registrada') else None,
            'estado_ciclo_descarga': ciclo_descarga_actual if ciclo_descarga_actual and ciclo_descarga_actual.get('en_proceso') else None,
            'pasos': pasos,
            'tiempo_planta': formatear_duracion_planta(log_autorizacion.LOG_FFECHAREGISTRO if log_autorizacion else None),
            'ingreso_autorizado_iso': log_autorizacion.LOG_FFECHAREGISTRO.isoformat() if log_autorizacion and log_autorizacion.LOG_FFECHAREGISTRO else '',
            'inicio_etapa_actual_iso': inicio_etapa_actual.isoformat() if inicio_etapa_actual else '',
            'tiempo_etapa': formatear_duracion_planta(inicio_etapa_actual),
            'ingreso_autorizado': timezone.localtime(log_autorizacion.LOG_FFECHAREGISTRO).strftime('%d/%m/%Y %H:%M') if log_autorizacion and log_autorizacion.LOG_FFECHAREGISTRO else '',
            'ultima_actualizacion': timezone.localtime((ultimo_log.OPL_FFECHAREGISTRO if ultimo_log else log_autorizacion.LOG_FFECHAREGISTRO)).strftime('%d/%m/%Y %H:%M') if (ultimo_log or log_autorizacion) else '',
            'nombre_flujo': nombre_flujo,
            'historial': historial,
            'detalle_json': json.dumps({
                'patente': texto_sin_informacion(valores_ingreso.get('patente')),
                'conductor': texto_sin_informacion(valores_ingreso.get('conductor')),
                'producto': nombre_producto_sap,
                'tipo_citacion': tipo_citacion or 'RECEPCION',
                'tipo_citacion_label': tipo_citacion_label,
                'secuencia': nombre_flujo,
                'ingreso_autorizado': timezone.localtime(log_autorizacion.LOG_FFECHAREGISTRO).strftime('%d/%m/%Y %H:%M') if log_autorizacion and log_autorizacion.LOG_FFECHAREGISTRO else '',
                'tiempo_planta': formatear_duracion_planta(log_autorizacion.LOG_FFECHAREGISTRO if log_autorizacion else None),
                'etapa_actual': etapa_actual,
                'estado_accion_toma_muestra': accion_toma_muestra if accion_toma_muestra and accion_toma_muestra.get('registrada') else None,
                'estado_ciclo_descarga': ciclo_descarga_actual if ciclo_descarga_actual and ciclo_descarga_actual.get('en_proceso') else None,
                'historial': historial,
            })
        })

    return render(request, 'home/CITACION/seguimiento_operacional.html', {
        'camiones': rows,
    })


def SEGUIMIENTO_OPERACIONAL_ELIMINAR_CAMION(request, pk):
    if request.method != 'POST':
        return JsonResponse({'success': False, 'message': 'Metodo no permitido.'}, status=405)

    if not request.user.is_superuser:
        return JsonResponse({'success': False, 'message': 'No tiene permisos para eliminar camiones activos.'}, status=403)

    Empresa = Verificar_empresa(request)
    if Empresa is None:
        return JsonResponse({'success': False, 'message': 'Debe seleccionar una empresa.'}, status=400)

    try:
        with transaction.atomic():
            citacion = CITACION.objects.select_related('EP_NID', 'PL_NID').get(
                pk=pk,
                EP_NID_id=Empresa,
                CI_BHABILITADO=True
            )

            if citacion.CI_CESTADO == CIT_RECHAZADO:
                return JsonResponse({
                    'success': True,
                    'message': 'El camion ya estaba eliminado del seguimiento operacional.'
                })

            ingreso_autorizado = SYSLOGGER.objects.filter(
                EP_NID_id=Empresa,
                LOG_COPERACION='AUTORIZA_INGRESO_PLANTA',
                LOG_CADD1=str(citacion.id)
            ).exists()
            if not ingreso_autorizado:
                return JsonResponse({
                    'success': False,
                    'message': 'La citacion no tiene ingreso a planta autorizado.'
                }, status=400)

            salida_confirmada = OPERACION_PLANTA_LOG.objects.filter(
                CI_NID=citacion,
                OPL_CPASO='Confirmar Salida',
                OPL_CESTADO=OPERACION_PLANTA_LOG.ESTADO_COMPLETADO
            ).exists()
            if salida_confirmada:
                return JsonResponse({
                    'success': False,
                    'message': 'El camion ya tiene salida confirmada.'
                }, status=400)

            valores_ingreso = obtener_valores_ingreso_camion(citacion)
            patente = texto_sin_informacion(valores_ingreso.get('patente'))
            ahora = timezone.now()

            citacion.CI_CESTADO = CIT_RECHAZADO
            citacion.CI_FFECHATERMINO = ahora
            citacion.save(update_fields=['CI_CESTADO', 'CI_FFECHATERMINO'])

            OPERACION_PLANTA_LOG.objects.create(
                US_NID=request.user,
                EP_NID=citacion.EP_NID,
                PL_NID=citacion.PL_NID,
                CI_NID=citacion,
                OPL_CPASO='Cancelacion seguimiento operacional',
                OPL_CPERFIL_RESPONSABLE='ADMIN',
                OPL_CESTADO=OPERACION_PLANTA_LOG.ESTADO_COMPLETADO,
                OPL_COBSERVACION='Camion activo eliminado/cancelado desde Seguimiento Operacional por usuario administrador.',
                OPL_FFECHAREGISTRO=ahora
            )

            registrar_log_camion_no_planificado(
                request.user,
                citacion.EP_NID,
                'CANCELA_SEG_OPER',
                f'Camion activo cancelado desde seguimiento operacional. Citacion #{citacion.id}. Patente: {patente}',
                citacion.id,
                patente
            )

        return JsonResponse({
            'success': True,
            'message': 'Camion eliminado del seguimiento operacional.'
        })
    except CITACION.DoesNotExist:
        return JsonResponse({'success': False, 'message': 'Citacion no encontrada.'}, status=404)
    except Exception as e:
        return JsonResponse({'success': False, 'message': str(e)}, status=500)


def export_citaciones_despachos_excel(request):

    try:
        if not request.user.is_superuser:
            usuario = request.user.id
            if not validar_perfiles_activos(usuario, "cit_listall"):
                messages.error(request, 'No tiene permisos para acceder a esta sección')
                return redirect('/')

        Empresa = Verificar_empresa(request)

        asignadas = obtener_secuencias_asignadas_usuario(request.user)

        fecha_desde = request.GET.get('fecha_desde')
        fecha_hasta = request.GET.get('fecha_hasta')
        secuencia_id = request.GET.getlist('secuencia')

        if isinstance(fecha_desde, str):
            fecha_desde = parse_date(fecha_desde)
        if isinstance(fecha_hasta, str):
            fecha_hasta = parse_date(fecha_hasta)

        queryset = CITACION.objects.filter(
            EP_NID_id=Empresa,
            CI_CTIPO=CIT_DESPACHO,
            CI_BHABILITADO=True
        ).annotate(
            valor_campo_38=Subquery(
                DATO_OPERACION.objects.filter(
                    CI_NID=OuterRef('pk'),
                    CAMP_NID_id=38
                ).values('DO_CVALOR')[:1]
            )
        )

        if asignadas.exists():
            queryset = queryset.filter(SC_NID_id__in=asignadas)

        if secuencia_id:
            queryset = queryset.filter(SC_NID__in=secuencia_id)

        if fecha_desde and fecha_hasta:
            queryset = queryset.filter(CI_FFECHACITACION__date__range=[fecha_desde, fecha_hasta])
        else:
            if fecha_desde:
                queryset = queryset.filter(CI_FFECHACITACION__date__gte=fecha_desde)
            if fecha_hasta:
                queryset = queryset.filter(CI_FFECHACITACION__date__lte=fecha_hasta)

        object_list = queryset.order_by('-id')

        workbook = openpyxl.Workbook()
        worksheet = workbook.active
        worksheet.title = "Citaciones Despachos"

        columnas = [
            'ID', 'Planificacion', 'Tipo de Documento', 'Número Documento',
            'Número Cupo', 'Fecha Citación', 'Nombre Secuencia',
            'Nombre Etapa', 'Cliente', 'Conductor', 'Celular Conductor', 'Patente', 'Tipo eje', 'Transportista'
        ]

        for col, header in enumerate(columnas, 1):
            worksheet.cell(row=1, column=col, value=header)

        for row, citacion in enumerate(object_list, 2):
            worksheet.cell(row=row, column=1, value=citacion.pk)
            worksheet.cell(row=row, column=2, value=citacion.PL_NID.id if citacion.PL_NID else '')
            worksheet.cell(row=row, column=3, value=citacion.CI_CTIPODOCUMENTO if citacion.CI_CTIPODOCUMENTO else '')
            worksheet.cell(row=row, column=4, value=citacion.valor_campo_38 if citacion.valor_campo_38 else citacion.CI_CNUMERODOCUMENTO)
            worksheet.cell(row=row, column=5, value=citacion.CI_NCUPO)
            worksheet.cell(row=row, column=6, value=citacion.CI_FFECHACITACION.strftime('%Y-%m-%d %H:%M') if citacion.CI_FFECHACITACION else '')
            worksheet.cell(row=row, column=7, value=citacion.SC_NID.SE_CCODIGO + ' - ' + citacion.SC_NID.SE_CNOMBRE if citacion.SC_NID else '')
            worksheet.cell(row=row, column=8, value=citacion.ETAPA_ACTUAL.ET_CCODIGO if citacion.ETAPA_ACTUAL else '')
            worksheet.cell(row=row, column=9, value=citacion.SN_NID.SN_CRAZONSOCIAL if citacion.SN_NID else '')
            valores_ingreso = obtener_valores_ingreso_camion(citacion)
            worksheet.cell(row=row, column=10, value=texto_sin_informacion(valores_ingreso.get('conductor')))
            worksheet.cell(row=row, column=11, value=texto_sin_informacion(valores_ingreso.get('celular_conductor')))
            worksheet.cell(row=row, column=12, value=texto_sin_informacion(valores_ingreso.get('patente')))
            worksheet.cell(row=row, column=13, value=texto_sin_informacion(valores_ingreso.get('cantidad_ejes')))
            worksheet.cell(row=row, column=14, value=texto_sin_informacion(valores_ingreso.get('transportista')))

        for column in worksheet.columns:
            max_length = 0
            column = [cell for cell in column]
            for cell in column:
                try:
                    if len(str(cell.value)) > max_length:
                        max_length = len(str(cell.value))
                except:
                    pass
            worksheet.column_dimensions[column[0].column_letter].width = max_length + 2

        response = HttpResponse(content_type='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')
        response['Content-Disposition'] = f'attachment; filename=citaciones_despachos_{timezone.now().strftime("%Y%m%d_%H%M%S")}.xlsx'
        workbook.save(response)
        return response

    except Exception as e:
        print(e)
        messages.error(request, f'Error al exportar a Excel: {str(e)}')
        return redirect('cit_listall_despachos')
