def CITACION_BACKWARD(request, pk):
    try:
        citacion = CITACION.objects.get(id = pk)
        empresa = citacion.EP_NID       
        etapa_actual = citacion.ETAPA_ACTUAL
        detalle_secuencia_actual = DETALLE_SECUENCIA.objects.get(EP_NID = citacion.EP_NID, SC_NID = citacion.SC_NID, ET_NID = etapa_actual)

        campos_etapa_actual = GetPreviewEtapa(etapa_actual.pk)
        if campos_etapa_actual:
            for campo in campos_etapa_actual:
                campo_obj = CAMPO.objects.get(id = campo[6])
                if campo_obj.CA_BASIGNARVALOR == True:
                    codigo_campo = campo_obj.CA_CCODIGO
                    update_field_citacion_null(pk, codigo_campo)
        
        detalle_etapa_anterior = DETALLE_SECUENCIA.objects.filter(EP_NID = citacion.EP_NID, SC_NID = citacion.SC_NID, SE_NPASO = detalle_secuencia_actual.SE_NPASO - 1).first()
        if detalle_etapa_anterior:
            datos_operacion = DATO_OPERACION.objects.filter(CI_NID = citacion, SC_NID = citacion.SC_NID, ET_NID = detalle_etapa_anterior.ET_NID)
            if datos_operacion:
                datos_operacion.delete()
            etapa_log = ETAPA_LOG.objects.get(CI_NID = citacion, SC_NID = citacion.SC_NID, ET_NID = detalle_etapa_anterior.ET_NID)
            etapa_log.EL_FFECHAFIN = None
            etapa_log.save()
            usuarios_responsables_str = detalle_etapa_anterior.USERS_RESPONSABLE_ID
            if usuarios_responsables_str:
                usuarios_responsables = usuarios_responsables_str.replace('[','').replace(']','').replace(' ','').replace("'","").replace('"','').split(',')
                for usuario_responsable in usuarios_responsables:
                    user = User.objects.get(id = usuario_responsable)
                    notificacion = NOTIFICACION.objects.create(
                        USER_SENDER_ID = request.user,
                        USER_RECEIVER_ID = user,
                        EP_NID = empresa,
                        NOT_CCONTENIDO = f'Citación {str(citacion.pk)} ha retornado a tu etapa {detalle_etapa_anterior.ET_NID.ET_CNOMBRE}',
                    )
                notificacion.NOT_CURL = f'/cit_listone/{citacion.pk}?notificacion={str(notificacion.pk)}'
                notificacion.save()
        else:
            messages.error(request, 'No se puede volver a la etapa anterior')
            return redirect(f'/cit_listone/{citacion.id}')
        
        etapa_log_actual = ETAPA_LOG.objects.get(CI_NID = citacion, SC_NID = citacion.SC_NID, ET_NID = etapa_actual)
        etapa_log_actual.delete()

        datos_operacion = DATO_OPERACION.objects.filter(CI_NID = citacion, SC_NID = citacion.SC_NID, ET_NID = etapa_actual)
        if datos_operacion:
            datos_operacion.delete()

        messages.success(request, 'Retorno a etapa anterior!')
        return redirect(f'/cit_listone/{citacion.id}')
    except Exception as e:
        print(e)
        messages.error(request, f'Error, {str(e)}')
        return redirect(f'/cit_listone/{pk}')

def ajax_validar_citaciones(request):
    try:
        id_planificacion = request.POST.get('id_planificacion')
        tableData = json.loads(request.POST.get('data'))
        es_venta = True if request.POST.get('venta') == 'true' else False
        planificacion = PLANIFICACION.objects.get(id = id_planificacion)
        hora_inicio_local = timezone.localtime(planificacion.PL_FFECHAINICIO).time()
        hora_fin_local = timezone.localtime(planificacion.PL_FFECHAFIN).time()
        advertencias = []
        
        for index, row in enumerate(tableData):
            # VALIDAR HORA DE CITACION
            hora_citacion = row['hora_citacion']
            hora_citacion_obj = datetime.strptime(hora_citacion, '%H:%M').time()
            if hora_citacion_obj < hora_inicio_local or hora_citacion_obj > hora_fin_local:
                return JsonResponse({
                    'valid': False, 
                    'msg': f'La hora de citación {index + 1} no está dentro del rango de la planificación',
                })

            # VALIDAR PROVEEDOR
            if not row["id_proveedor"]:
                return JsonResponse({
                    'valid': False, 
                    'msg': f'La citación {index + 1} no posee proveedor valido',
                })
            proveedor = SOCIONEGOCIO.objects.get(id = row["id_proveedor"])
            
            # VALIDAR CONDUCTOR
            if not row['id_conductor']:
                return JsonResponse({
                    'valid': False, 
                    'msg': f'La citación {index + 1} no posee conductor valido',
                })
            if proveedor.SN_CRAZONSOCIAL != 'Puesto en planta':
                conductor = CONDUCTOR.objects.get(id = row['id_conductor'])
                
                # VERIFICAR DOCUMENTOS DEL CONDUCTOR
                if conductor.CON_CNOMBRE != 'CONDUCTOR':
                    documentos_conductor = conductor.ESTADO_DOCUMENTOS
                    if documentos_conductor:
                        for doc in documentos_conductor:
                            if doc[1] == -999:
                                advertencias.append(f'El conductor {conductor.CON_CNOMBRE} {conductor.CON_CAPELLIDO} no tiene el documento {doc[0]} cargado')
                            elif doc[1] <= 0:
                                advertencias.append(f'El documento {doc[0]} del conductor {conductor.CON_CNOMBRE} {conductor.CON_CAPELLIDO} está vencido')
                            elif doc[1] <= 30:
                                advertencias.append(f'El documento {doc[0]} del conductor {conductor.CON_CNOMBRE} {conductor.CON_CAPELLIDO} vence en {doc[1]} días')
                                
            # VALIDAR CAMION
            if not row['id_camion']:
                return JsonResponse({
                    'valid': False, 
                    'msg': f'La citación {index + 1} no posee camión valido',
                })
            if proveedor.SN_CRAZONSOCIAL != 'Puesto en planta':

                camion = CAMION.objects.get(id = row['id_camion'])
            
                # VERIFICAR DOCUMENTOS DEL CAMION
                if camion.CAM_CPATENTE != 'CAMION_GENERICO':
                    documentos_camion = camion.ESTADO_DOCUMENTOS
                    if documentos_camion:
                        for doc in documentos_camion:
                            if doc[1] == -999:
                                advertencias.append(f'El camión {camion.CAM_CPATENTE} no tiene el documento {doc[0]} cargado')
                            elif doc[1] <= 0:
                                advertencias.append(f'El documento {doc[0]} del camión {camion.CAM_CPATENTE} está vencido')
                            elif doc[1] <= 30:
                                advertencias.append(f'El documento {doc[0]} del camión {camion.CAM_CPATENTE} vence en {doc[1]} días')

            # VALIDAR SECUENCIA
            if not row['id_secuencia']:
                return JsonResponse({
                    'valid': False, 
                    'msg': f'La citación {index + 1} no posee secuencia valida',
                })

            # VALIDAR ITEM
            if not row['id_producto']:
                return JsonResponse({
                    'valid': False, 
                    'msg': f'La citación {index + 1} no posee item valido',
                })

        # VALIDAR NUMERO DE CITACIONES
        num_citaciones_planificacion = CITACION.objects.filter(PL_NID = planificacion).count() + len(tableData)
        if num_citaciones_planificacion > planificacion.PL_NCANTIDADCUPOS:
            return JsonResponse({
                'valid': True, 
                'continue': False,
                'msg': f'La planificación ya posee el número máximo de citaciones, ¿quieres marcarla como sobrecupo?',
            })
            
        # Si hay advertencias, las mostramos pero permitimos continuar
        if advertencias:
            return JsonResponse({
                'valid': True,
                'continue': False,
                'has_warnings': True,
                'warnings': advertencias,
                'msg': f'Se encontraron problemas con documentos.{advertencias} ¿Desea continuar de todas formas?'
            })
            
        return JsonResponse({'valid': True, 'continue': True})
    except Exception as e:
        print(e)
        return JsonResponse({'valid': False, 'msg': str(e)})

def DOWNLOAD_DATO_OPERACION_FILE(request, pk):
    try:
        dato_operacion = DATO_OPERACION.objects.get(id=pk)
        empresa = Verificar_empresa(request)

        if empresa is not None and dato_operacion.EP_NID_id != empresa:
            messages.error(request, 'Documento no disponible para la empresa activa')
            return redirect('/')

        if request.user.is_superuser == False:
            usuario = request.user.id
            tiene_permiso_citacion = validar_perfiles_activos(usuario, "cit_listone")
            tiene_permiso_operacion = usuario_es_operacion_planta(request.user)
            if not tiene_permiso_citacion and not tiene_permiso_operacion:
                messages.error(request, 'No tiene permisos para acceder a esta seccion')
                return redirect('/')

        file_path = dato_operacion.DO_CVALOR
        if os.path.exists(file_path):
            response = FileResponse(open(file_path, 'rb'))
            response['Content-Disposition'] = f'attachment; filename="{os.path.basename(file_path)}"'
            return response

        messages.error(request, 'Documento no encontrado')
        return redirect(f'/cit_listone/{dato_operacion.CI_NID.pk}')
    except Exception as e:
        print(e)
        return JsonResponse({'success': False})


def aplicar_filtros_expediente_citacion(queryset, params):
    citacion = str(params.get('citacion') or '').strip()
    producto_sap = str(params.get('producto_sap') or '').strip()
    patente = str(params.get('patente') or '').strip()
    codigo_sap = str(params.get('codigo_sap') or '').strip()
    pedido_sap = str(params.get('pedido_sap') or '').strip()
    cliente = str(params.get('cliente') or '').strip()
    proveedor = str(params.get('proveedor') or '').strip()
    fecha_desde = parse_date(str(params.get('fecha_desde') or '').strip())
    fecha_hasta = parse_date(str(params.get('fecha_hasta') or '').strip())
    tipo_documento = str(params.get('tipo_documento') or '').strip()

    if citacion and citacion.isdigit():
        queryset = queryset.filter(id=citacion)
    elif citacion:
        queryset = queryset.none()
    if producto_sap:
        queryset = queryset.filter(
            Q(detalle_operacional__CDO_CINSUMO__icontains=producto_sap)
            | Q(citacion_item__IT_NID__IT_CNOMBRE__icontains=producto_sap)
        )
    if patente:
        queryset = queryset.filter(
            Q(CA_NID__CAM_CPATENTE__icontains=patente)
            | Q(dato_operacion__CAMP_NID__CA_CCODIGO='ING_PATENTE', dato_operacion__DO_CVALOR__icontains=patente)
        )
    if codigo_sap:
        queryset = queryset.filter(detalle_operacional__CDO_CCODIGO_SAP__icontains=codigo_sap)
    if pedido_sap:
        queryset = queryset.filter(detalle_operacional__CDO_CPEDIDO_SAP__icontains=pedido_sap)
    if cliente:
        queryset = queryset.filter(SN_NID__SN_CRAZONSOCIAL__icontains=cliente)
    if proveedor:
        queryset = queryset.filter(PRO_NID__SN_CRAZONSOCIAL__icontains=proveedor)
    if fecha_desde:
        queryset = queryset.filter(CI_FFECHACITACION__date__gte=fecha_desde)
    if fecha_hasta:
        queryset = queryset.filter(CI_FFECHACITACION__date__lte=fecha_hasta)
    if tipo_documento:
        queryset = queryset.filter(documentos_expediente__CD_CTIPO=tipo_documento, documentos_expediente__CD_BACTIVO=True)
    return queryset.distinct()


def EXPEDIENTE_CITACION_LIST(request):
    empresa = Verificar_empresa(request)
    if empresa is None:
        messages.error(request, 'Debe seleccionar una empresa activa')
        return redirect('/')

    sincronizar_expedientes_legacy_empresa(empresa)
    citaciones = CITACION.objects.select_related(
        'SN_NID',
        'PRO_NID',
        'CA_NID',
        'detalle_operacional',
    ).filter(
        EP_NID_id=empresa,
        CI_BHABILITADO=True,
        documentos_expediente__CD_BACTIVO=True
    )
    citaciones = aplicar_filtros_expediente_citacion(citaciones, request.GET)
    citaciones = citaciones.order_by('-CI_FFECHACITACION', '-id')

    paginator = Paginator(citaciones, 30)
    page_number = request.GET.get('page')
    page_obj = paginator.get_page(page_number)
    querystring = request.GET.copy()
    querystring.pop('page', None)

    citaciones_pagina = list(page_obj.object_list)
    documentos_por_citacion = {}
    documentos = CITACION_DOCUMENTO.objects.select_related('US_SUBE_NID').filter(
        CI_NID_id__in=[citacion.id for citacion in citaciones_pagina],
        EP_NID_id=empresa,
        CD_BACTIVO=True
    ).order_by('CD_CTIPO', '-CD_FFECHASUBIDA')
    tipo_documento = str(request.GET.get('tipo_documento') or '').strip()
    if tipo_documento:
        documentos = documentos.filter(CD_CTIPO=tipo_documento)
    for documento in documentos:
        documentos_por_citacion.setdefault(documento.CI_NID_id, []).append(documento)

    expedientes = []
    for citacion in citaciones_pagina:
        valores_ingreso = obtener_valores_ingreso_camion(citacion)
        item = CITACION_ITEM.objects.select_related('IT_NID').filter(CI_NID=citacion).first()
        detalle = getattr(citacion, 'detalle_operacional', None)
        proveedor_sap = (detalle.CDO_CPRODUCTOR if detalle else '') or (citacion.PRO_NID.SN_CRAZONSOCIAL if citacion.PRO_NID else '')
        expedientes.append({
            'citacion': citacion,
            'detalle': detalle,
            'producto': (detalle.CDO_CINSUMO if detalle else '') or (item.IT_NID.IT_CNOMBRE if item and item.IT_NID else ''),
            'codigo_sap': detalle.CDO_CCODIGO_SAP if detalle else '',
            'pedido_sap': detalle.CDO_CPEDIDO_SAP if detalle else '',
            'patente': valores_ingreso.get('patente') or '',
            'cliente': citacion.SN_NID.SN_CRAZONSOCIAL if citacion.SN_NID else '',
            'proveedor': proveedor_sap,
            'documentos': documentos_por_citacion.get(citacion.id, []),
        })

    return render(request, 'home/EXPEDIENTE/expediente_list.html', {
        'page_obj': page_obj,
        'expedientes': expedientes,
        'tipos_documento': EXPEDIENTE_TIPO_LABELS.items(),
        'filtros': request.GET,
        'querystring': querystring.urlencode(),
        'puede_administrar': usuario_puede_administrar_expediente(request.user),
        'empresa_query_param': request.GET.get(EMPRESA_ACTIVA_PARAM) or request.GET.get('empresa_id') or empresa,
    })


def EXPEDIENTE_CITACION_DETAIL(request, pk):
    empresa = Verificar_empresa(request)
    citacion = get_object_or_404(
        CITACION.objects.select_related('SN_NID', 'PRO_NID', 'PL_NID', 'SC_NID'),
        pk=pk,
        EP_NID_id=empresa
    )
    sincronizar_expediente_legacy_citacion(citacion)

    documentos_activos = {
        documento.CD_CTIPO: documento
        for documento in CITACION_DOCUMENTO.objects.select_related('US_SUBE_NID').filter(
            CI_NID=citacion,
            EP_NID_id=empresa,
            CD_BACTIVO=True
        )
    }
    historial = CITACION_DOCUMENTO.objects.select_related('US_SUBE_NID', 'US_MODIFICA_NID').filter(
        CI_NID=citacion,
        EP_NID_id=empresa
    ).order_by('-CD_FFECHASUBIDA')

    documentos = []
    for tipo, etiqueta in EXPEDIENTE_TIPO_LABELS.items():
        documentos.append({
            'tipo': tipo,
            'etiqueta': etiqueta,
            'documento': documentos_activos.get(tipo),
        })

    detalle = getattr(citacion, 'detalle_operacional', None)
    proveedor_sap = (detalle.CDO_CPRODUCTOR if detalle else '') or (citacion.PRO_NID.SN_CRAZONSOCIAL if citacion.PRO_NID else '')
    return render(request, 'home/EXPEDIENTE/expediente_detail.html', {
        'citacion': citacion,
        'detalle': detalle,
        'proveedor_sap': proveedor_sap,
        'documentos': documentos,
        'historial': historial,
        'puede_administrar': usuario_puede_administrar_expediente(request.user),
    })


def obtener_documento_expediente_autorizado(request, pk):
    empresa = Verificar_empresa(request)
    documento = get_object_or_404(
        CITACION_DOCUMENTO.objects.select_related('CI_NID', 'EP_NID'),
        pk=pk,
        EP_NID_id=empresa
    )
    return documento


def responder_documento_expediente(request, pk, descargar=False):
    documento = obtener_documento_expediente_autorizado(request, pk)
    file_path = _resolver_ruta_archivo_citacion(documento.CD_CRUTA_ARCHIVO)
    if not os.path.exists(file_path):
        messages.error(request, 'Documento no encontrado')
        return redirect('expediente_citacion_detail', pk=documento.CI_NID_id)

    registrar_log_camion_no_planificado(
        request.user,
        documento.EP_NID,
        'DOC_CIT_DESC' if descargar else 'DOC_CIT_VER',
        f'Documento {documento.CD_CTIPO} {"descargado" if descargar else "visto"} desde expediente de citacion #{documento.CI_NID_id}',
        documento.CI_NID_id,
        documento.CD_CTIPO
    )
    response = FileResponse(open(file_path, 'rb'), as_attachment=descargar, filename=documento.CD_CNOMBRE_ARCHIVO)
    if not descargar:
        response['Content-Disposition'] = f'inline; filename="{documento.CD_CNOMBRE_ARCHIVO}"'
    return response


def EXPEDIENTE_CITACION_DOCUMENTO_VER(request, pk):
    return responder_documento_expediente(request, pk, descargar=False)


def EXPEDIENTE_CITACION_DOCUMENTO_DESCARGAR(request, pk):
    return responder_documento_expediente(request, pk, descargar=True)


def EXPEDIENTE_CITACION_DOCUMENTO_REEMPLAZAR(request, pk):
    documento = obtener_documento_expediente_autorizado(request, pk)
    if not usuario_puede_administrar_expediente(request.user):
        messages.error(request, 'No tiene permisos para reemplazar documentos')
        return redirect('expediente_citacion_detail', pk=documento.CI_NID_id)
    if request.method != 'POST':
        return redirect('expediente_citacion_detail', pk=documento.CI_NID_id)

    archivo = request.FILES.get('archivo')
    if not archivo:
        messages.error(request, 'Debe seleccionar un archivo')
        return redirect('expediente_citacion_detail', pk=documento.CI_NID_id)

    ruta_archivo, nombre_archivo = guardar_archivo_expediente_citacion(
        documento.CI_NID,
        documento.CD_CTIPO,
        archivo
    )
    nuevo_documento = registrar_documento_expediente(
        documento.CI_NID,
        documento.CD_CTIPO,
        ruta_archivo,
        nombre_archivo,
        request.user,
        dato_operacion=documento.DO_NID
    )
    registrar_log_camion_no_planificado(
        request.user,
        documento.EP_NID,
        'DOC_CIT_REEMP',
        f'Documento {documento.CD_CTIPO} reemplazado en expediente de citacion #{documento.CI_NID_id}',
        documento.CI_NID_id,
        nuevo_documento.id
    )
    messages.success(request, 'Documento reemplazado correctamente')
    return redirect('expediente_citacion_detail', pk=documento.CI_NID_id)


def usuario_puede_ver_archivo_eli(user):
    if getattr(user, 'is_superuser', False):
        return True
    return (
        usuario_es_operacion_planta(user)
        or usuario_es_planificador(user)
        or validar_perfiles_activos(user.id, "cit_listone")
        or validar_perfiles_activos(user.id, "pla_listone")
    )


def eli_texto(valor, defecto='No disponible'):
    if valor is None or valor == '':
        return defecto
    return str(valor)


def eli_fecha(valor, defecto='No disponible'):
    if not valor:
        return defecto
    try:
        return timezone.localtime(valor).strftime('%d/%m/%Y %H:%M:%S')
    except Exception:
        return defecto


def eli_usuario(usuario):
    if not usuario:
        return 'No disponible'
    nombre = f'{getattr(usuario, "first_name", "")} {getattr(usuario, "last_name", "")}'.strip()
    return nombre or getattr(usuario, 'username', '') or f'Usuario ID {getattr(usuario, "id", "")}'


def eli_texto_vacio(valor):
    if valor in [None, '']:
        return ''
    return str(valor)


def eli_fecha_vacia(valor):
    if not valor:
        return ''
    try:
        return timezone.localtime(valor).strftime('%d/%m/%Y %H:%M:%S')
    except Exception:
        return ''


def eli_fecha_solo_dia_vacia(valor):
    if not valor:
        return ''
    try:
        return timezone.localtime(valor).strftime('%d/%m/%Y')
    except Exception:
        return ''


def eli_usuario_vacio(usuario):
    if not usuario:
        return ''
    nombre = f'{getattr(usuario, "first_name", "")} {getattr(usuario, "last_name", "")}'.strip()
    return nombre or getattr(usuario, 'username', '') or ''


def eli_estado_auditoria(log):
    if not log:
        return 'Pendiente'
    estado = str(getattr(log, 'OPL_CESTADO', '') or '').strip()
    return estado.title() if estado else 'Completado'


def eli_auditoria_operacion(log, responsable=''):
    return {
        'responsable': responsable or (log.OPL_CPERFIL_RESPONSABLE if log else ''),
        'usuario_responsable': eli_usuario_vacio(log.US_NID) if log else '',
        'usuario_aprobador': eli_usuario_vacio(log.US_NID) if log else '',
        'fecha_inicio': eli_fecha_vacia(log.OPL_FFECHAREGISTRO) if log else '',
        'fecha_termino': eli_fecha_vacia(log.OPL_FFECHAREGISTRO) if log else '',
        'fecha': eli_fecha_vacia(log.OPL_FFECHAREGISTRO) if log else '',
        'estado': eli_estado_auditoria(log),
    }


def eli_fila(label, value):
    return {'label': label, 'value': eli_texto_vacio(value)}


def eli_etapa(numero, titulo, datos, auditoria):
    return {
        'numero': numero,
        'titulo': titulo,
        'datos': datos,
        'auditoria': auditoria,
    }


def eli_parse_json_seguro(valor):
    texto = str(valor or '').strip()
    if not texto or not (texto.startswith('{') or texto.startswith('[')):
        return None
    try:
        data = json.loads(texto)
    except (TypeError, ValueError):
        return None
    return data if isinstance(data, (dict, list)) else None


def eli_metadata_rows(metadata):
    if not isinstance(metadata, dict):
        return []
    etiquetas = {
        'peso_neto': 'Peso neto',
        'folio': 'Folio',
        'nombre_archivo_pdf': 'Archivo PDF',
        'fecha_hora_ticket': 'Fecha ticket',
        'resultado_calidad': 'Resultado calidad',
        'comentario': 'Comentario',
        'documento_nombre': 'Documento',
        'sitio_descarga': 'Sitio descarga',
        'bomba_descarga': 'Bomba descarga',
        'estanque_destino': 'Estanque destino',
        'tipo_descarga': 'Tipo descarga',
        'inicio_descarga': 'Inicio descarga',
        'fin_descarga': 'Fin descarga',
        'duracion_legible': 'Duracion',
        'recepcion_conforme': 'Recepcion conforme',
        'observacion_descarga': 'Observacion descarga',
        'paso_operacion': 'Paso operacion',
        'usuario': 'Usuario',
        'usuario_inicio': 'Usuario inicio',
        'usuario_fin': 'Usuario fin',
        'fecha_hora': 'Fecha/hora',
        'fecha_iso': 'Fecha ISO',
    }
    rows = []
    for llave, etiqueta in etiquetas.items():
        valor = metadata.get(llave)
        if valor not in [None, '']:
            rows.append({'label': etiqueta, 'value': valor})
    return rows


def eli_duracion(inicio, fin):
    if not inicio or not fin:
        return 'No disponible'
    try:
        total = max(int((fin - inicio).total_seconds()), 0)
    except Exception:
        return 'No disponible'
    dias = total // 86400
    horas = (total % 86400) // 3600
    minutos = (total % 3600) // 60
    segundos = total % 60
    if dias:
        return f'{dias} dias {horas:02d}:{minutos:02d}:{segundos:02d}'
    return f'{horas:02d}:{minutos:02d}:{segundos:02d}'


def eli_primer_log_operacion(logs, paso):
    for log in logs:
        if log.OPL_CPASO == paso:
            return log
    return None


def eli_dato_metadata(datos_por_codigo, codigo):
    dato = datos_por_codigo.get(codigo)
    if not dato:
        return {}
    metadata = eli_parse_json_seguro(dato.DO_CVALOR)
    return metadata if isinstance(metadata, dict) else {}


def eli_patente_consolidada_despacho(citacion, datos_por_codigo=None, valores_ingreso=None):
    datos_por_codigo = datos_por_codigo or {}
    valores_ingreso = valores_ingreso or {}
    camion_patio = CAMION_PATIO.objects.filter(CI_NID=citacion).order_by('-CPA_FFECHAACTUALIZACION', '-id').first()
    try:
        detalle = citacion.detalle_despacho
    except CITACION_DESPACHO_DETALLE.DoesNotExist:
        detalle = None
    dato_patente_legacy = datos_por_codigo.get('DATO_ING_PATENTE') or datos_por_codigo.get('ING_PATENTE')
    dato_campo_110 = None
    for dato in datos_por_codigo.values():
        if getattr(dato, 'CAMP_NID_id', None) == 110:
            dato_campo_110 = dato
            break
    return texto_o_primero(
        camion_patio.CPA_CPATENTE if camion_patio else '',
        detalle.CDD_CPATENTE if detalle else '',
        dato_campo_110.DO_CVALOR if dato_campo_110 else '',
        dato_patente_legacy.DO_CVALOR if dato_patente_legacy else '',
        valores_ingreso.get('patente'),
        citacion.CA_NID.CAM_CPATENTE if citacion.CA_NID else '',
    )


def eli_limpiar_texto_despacho(valor, patente_actual):
    texto = eli_texto_vacio(valor)
    if not texto:
        return ''
    if patente_actual:
        texto = re.sub(
            r'(Patente\s+)[A-Z0-9\-]+(\s+autorizada\s+para\s+operacion\s+en\s+planta)',
            rf'\1{patente_actual}\2',
            texto,
            flags=re.IGNORECASE,
        )
        texto = re.sub(
            r'(Patente\s+)[A-Z0-9\-]+(\s+autorizada\s+para\s+operaci[oó]n\s+en\s+planta)',
            rf'\1{patente_actual}\2',
            texto,
            flags=re.IGNORECASE,
        )
    return texto


def eli_fila_despacho(label, value, patente_actual=''):
    return eli_fila(label, eli_limpiar_texto_despacho(value, patente_actual))


def eli_json_field(data, *path):
    value = data
    for key in path:
        if isinstance(value, dict):
            value = value.get(key)
        elif isinstance(value, list) and isinstance(key, int) and len(value) > key:
            value = value[key]
        else:
            return ''
    return value


def eli_log_por_paso(logs, paso):
    encontrados = [log for log in logs if log.OPL_CPASO == paso]
    return encontrados[-1] if encontrados else None


def eli_ticket_row(ticket, key, default=''):
    return ticket.get(key) if isinstance(ticket, dict) else default


def eli_auditoria_despacho(log, responsable=''):
    return eli_auditoria_operacion(log, responsable)


def eli_observacion_despacho(log, patente_actual=''):
    if not log:
        return ''
    metadata = eli_parse_json_seguro(log.OPL_COBSERVACION)
    if isinstance(metadata, dict):
        for key in ['mensaje_corto', 'observacion_descarga', 'observacion', 'resultado', 'message']:
            if metadata.get(key):
                return eli_limpiar_texto_despacho(metadata.get(key), patente_actual)
        return ''
    return eli_limpiar_texto_despacho(log.OPL_COBSERVACION, patente_actual)


def eli_estado_sap_despacho(draft_status, update_status):
    if update_status.get('updated'):
        return 'Borrador actualizado con peso salida'
    if draft_status.get('created'):
        return 'Borrador creado'
    return 'Pendiente'


def eli_sap_despacho_resumen(citacion, detalle_despacho, draft_status, update_status):
    draft_request = draft_status.get('request_json') or {}
    update_request = update_status.get('request_json') or {}
    payload_base = update_request or draft_request
    line = eli_json_field(payload_base, 'DocumentLines', 0) or {}
    batch = eli_json_field(line, 'BatchNumbers', 0) or {}
    source_quantity = eli_json_field(draft_request, 'DocumentLines', 0, 'Quantity')
    updated_quantity = eli_json_field(update_request, 'DocumentLines', 0, 'Quantity') or update_status.get('peso_salida')
    return {
        'series': payload_base.get('Series') or draft_request.get('Series'),
        'doc_object_code': payload_base.get('DocObjectCode') or draft_request.get('DocObjectCode'),
        'card_code': payload_base.get('CardCode') or getattr(detalle_despacho, 'CDD_CSAP_CLIENTE_CODIGO', ''),
        'card_name': getattr(detalle_despacho, 'CDD_CSAP_CLIENTE_NOMBRE', '') or (citacion.SN_NID.SN_CRAZONSOCIAL if citacion.SN_NID else ''),
        'agreement_no': line.get('AgreementNo') or getattr(detalle_despacho, 'CDD_CSAP_ABS_ID', ''),
        'agreement_visible': getattr(detalle_despacho, 'CDD_CSAP_NUMERO_ACUERDO', ''),
        'linea_acuerdo': getattr(detalle_despacho, 'CDD_CSAP_LINEA_ACUERDO', ''),
        'item_code': line.get('ItemCode') or getattr(detalle_despacho, 'CDD_CSAP_CODIGO_PRODUCTO', ''),
        'item_name': getattr(detalle_despacho, 'CDD_CSAP_NOMBRE_PRODUCTO', ''),
        'warehouse_code': line.get('WarehouseCode') or '',
        'batch_number': batch.get('BatchNumber') or '',
        'quantity_inicial': source_quantity,
        'quantity_actualizada': updated_quantity,
    }


def eli_documentos_despacho(citacion, fecha_generacion='', usuario_genera=''):
    documentos = []
    for documento in CITACION_DOCUMENTO.objects.select_related('US_SUBE_NID').filter(
        CI_NID=citacion,
        EP_NID=citacion.EP_NID,
        CD_BACTIVO=True
    ).order_by('CD_CTIPO', '-CD_FFECHASUBIDA'):
        documentos.append({
            'id': documento.id,
            'tipo': documento.get_CD_CTIPO_display(),
            'codigo': documento.CD_CTIPO,
            'archivo': os.path.basename(documento.CD_CNOMBRE_ARCHIVO or documento.CD_CRUTA_ARCHIVO or ''),
            'fecha': eli_fecha(documento.CD_FFECHASUBIDA),
            'usuario': eli_usuario(documento.US_SUBE_NID),
        })
    for camion in CAMION_PATIO.objects.filter(CI_NID=citacion).prefetch_related('adjuntos'):
        for adjunto in camion.adjuntos.all().order_by('CPA_CTIPO_DOCUMENTO', '-CPA_FFECHACARGA'):
            documentos.append({
                'id': '',
                'tipo': adjunto.get_CPA_CTIPO_DOCUMENTO_display(),
                'codigo': adjunto.CPA_CTIPO_DOCUMENTO,
                'archivo': os.path.basename(adjunto.CPA_FARCHIVO.name or ''),
                'fecha': eli_fecha(adjunto.CPA_FFECHACARGA),
                'usuario': eli_usuario(adjunto.US_CARGA_ID),
            })
    return documentos


def construir_archivo_eli_despacho(citacion, request=None):
    sincronizar_expediente_legacy_citacion(citacion)
    detalle_dict = detalle_operacional_dict(citacion)
    valores_ingreso = obtener_valores_ingreso_camion(citacion)
    item = CITACION_ITEM.objects.select_related('IT_NID').filter(CI_NID=citacion).first()
    try:
        detalle_despacho = citacion.detalle_despacho
    except CITACION_DESPACHO_DETALLE.DoesNotExist:
        detalle_despacho = None

    datos_operacion = list(DATO_OPERACION.objects.select_related('CAMP_NID', 'US_NID', 'ET_NID').filter(
        CI_NID=citacion
    ).order_by('DO_FFECHAREGISTRO', 'id'))
    datos_por_codigo = {}
    for dato in datos_operacion:
        codigo = dato.CAMP_NID.CA_CCODIGO if dato.CAMP_NID else f'DATO_{dato.id}'
        datos_por_codigo[codigo] = dato

    logs_operacion = list(OPERACION_PLANTA_LOG.objects.select_related('US_NID').filter(
        CI_NID=citacion
    ).order_by('OPL_FFECHAREGISTRO', 'id'))

    patente_actual = eli_patente_consolidada_despacho(citacion, datos_por_codigo, valores_ingreso)
    resumen_sap = _resumen_sap_despacho_bodega_externa(citacion).get('datos', {})
    draft_status = get_sap_despacho_draft_status(citacion)
    update_status = get_sap_despacho_update_status(citacion)
    sap_resumen = eli_sap_despacho_resumen(citacion, detalle_despacho, draft_status, update_status)

    ticket_ent = eli_dato_metadata(datos_por_codigo, _codigo_campo_ticket_pesaje('ENT'))
    ticket_sal = eli_dato_metadata(datos_por_codigo, _codigo_campo_ticket_pesaje('SAL'))
    peso_entrada = eli_ticket_row(ticket_ent, 'peso_neto')
    peso_salida = eli_ticket_row(ticket_sal, 'peso_neto') or update_status.get('peso_salida')
    diferencia_peso = ''
    try:
        if peso_entrada not in [None, ''] and peso_salida not in [None, '']:
            diferencia_peso = Decimal(str(peso_entrada)) - Decimal(str(peso_salida))
    except (InvalidOperation, ValueError):
        diferencia_peso = ''

    log_pesaje_entrada = eli_log_por_paso(logs_operacion, 'Pesaje Entrada')
    log_autorizacion_inicial = eli_log_por_paso(logs_operacion, PASO_AUTORIZACION_SALIDA_INICIAL)
    log_ingreso_planta = eli_log_por_paso(logs_operacion, PASO_INGRESO_PLANTA_DESPACHO)
    log_pesaje_salida = eli_log_por_paso(logs_operacion, 'Pesaje Salida')
    log_draft = eli_log_por_paso(logs_operacion, 'BORRADOR_SAP_DESPACHO_ENVIO')
    log_update = eli_log_por_paso(logs_operacion, 'UPDATE_SAP_DESPACHO_ENVIO') or eli_log_por_paso(logs_operacion, 'SAP_UPDATE_DRAFT_ERROR')
    log_autorizar = eli_log_por_paso(logs_operacion, PASO_AUTORIZAR_SALIDA)
    log_confirmar = eli_log_por_paso(logs_operacion, PASO_CONFIRMAR_SALIDA)

    cliente_nombre = texto_o_primero(
        sap_resumen.get('card_name'),
        resumen_sap.get('cliente_nombre'),
        detalle_dict.get('cliente_nombre'),
        citacion.SN_NID.SN_CRAZONSOCIAL if citacion.SN_NID else '',
    )
    transportista = texto_o_primero(
        getattr(detalle_despacho, 'CDD_CEMPRESA_TRANSPORTE', '') if detalle_despacho else '',
        valores_ingreso.get('transportista'),
        resumen_sap.get('transportista'),
    )
    conductor = texto_o_primero(
        getattr(detalle_despacho, 'CDD_CCONDUCTOR', '') if detalle_despacho else '',
        valores_ingreso.get('conductor'),
        resumen_sap.get('conductor'),
    )
    telefono = texto_o_primero(
        getattr(detalle_despacho, 'CDD_CTELEFONO_CONDUCTOR', '') if detalle_despacho else '',
        valores_ingreso.get('celular_conductor'),
    )
    producto = texto_o_primero(sap_resumen.get('item_name'), resumen_sap.get('sap_nombre_producto'), detalle_dict.get('insumo'), item.IT_NID.IT_CNOMBRE if item and item.IT_NID else '')
    codigo_producto = texto_o_primero(sap_resumen.get('item_code'), resumen_sap.get('sap_codigo_producto'), detalle_dict.get('codigo'))
    oc_cliente = texto_o_primero(getattr(detalle_despacho, 'CDD_CSAP_OC_CLIENTE', '') if detalle_despacho else '', resumen_sap.get('oc_cliente'), detalle_dict.get('pedido'))
    cantidad_intentada = texto_o_primero(getattr(detalle_despacho, 'CDD_NCANTIDAD_INTENTADA_DESPACHAR', '') if detalle_despacho else '', resumen_sap.get('cantidad_intentada'))
    condicion_bodega = texto_o_primero(getattr(detalle_despacho, 'CDD_CCONDICION_ENTREGA', '') if detalle_despacho else '', getattr(detalle_despacho, 'CDD_CBODEGA', '') if detalle_despacho else '', resumen_sap.get('bodega_condicion'))

    fecha_generacion = eli_fecha(timezone.now())
    usuario_genera = eli_usuario(request.user) if request else ''
    documentos = eli_documentos_despacho(citacion, fecha_generacion, usuario_genera)

    encabezado_eli = [
        eli_fila_despacho('Numero citacion', citacion.id, patente_actual),
        eli_fila_despacho('Fecha citacion', eli_fecha_solo_dia_vacia(citacion.CI_FFECHACITACION), patente_actual),
        eli_fila_despacho('Empresa', citacion.EP_NID.EP_CRAZONSOCIAL if citacion.EP_NID else '', patente_actual),
        eli_fila_despacho('Tipo operacion', 'DESPACHO', patente_actual),
        eli_fila_despacho('Flujo / secuencia', citacion.SC_NID.SE_CNOMBRE if citacion.SC_NID else '', patente_actual),
        eli_fila_despacho('Estado operacional', citacion.CI_CESTADO, patente_actual),
        eli_fila_despacho('Patente', patente_actual, patente_actual),
        eli_fila_despacho('Conductor', conductor, patente_actual),
        eli_fila_despacho('Telefono conductor', normalizar_celular_conductor_visible(telefono), patente_actual),
        eli_fila_despacho('Transportista', transportista, patente_actual),
        eli_fila_despacho('Cliente SAP / CardName', cliente_nombre, patente_actual),
        eli_fila_despacho('CardCode', sap_resumen.get('card_code'), patente_actual),
        eli_fila_despacho('OC Cliente / NumAtCard', oc_cliente, patente_actual),
        eli_fila_despacho('Codigo producto SAP', codigo_producto, patente_actual),
        eli_fila_despacho('Producto SAP', producto, patente_actual),
        eli_fila_despacho('Cantidad intentada a despachar', cantidad_intentada, patente_actual),
        eli_fila_despacho('Condicion entrega / bodega', condicion_bodega, patente_actual),
    ]

    etapas_eli = [
        eli_etapa(1, 'Datos comerciales / SAP despacho', [
            eli_fila_despacho('Guia', citacion.CI_CNUMERODOCUMENTO, patente_actual),
            eli_fila_despacho('Cliente', cliente_nombre, patente_actual),
            eli_fila_despacho('CardCode', sap_resumen.get('card_code'), patente_actual),
            eli_fila_despacho('Codigo SAP', codigo_producto, patente_actual),
            eli_fila_despacho('Pedido SAP / OC Cliente', oc_cliente, patente_actual),
            eli_fila_despacho('Contrato SAP visible', sap_resumen.get('agreement_visible'), patente_actual),
            eli_fila_despacho('SAP AbsID / AgreementNo interno', sap_resumen.get('agreement_no'), patente_actual),
            eli_fila_despacho('Insumo / Producto SAP', producto, patente_actual),
            eli_fila_despacho('Cantidad intentada', cantidad_intentada, patente_actual),
            eli_fila_despacho('Peso salida real', peso_salida, patente_actual),
            eli_fila_despacho('Transportista', transportista, patente_actual),
            eli_fila_despacho('Patente', patente_actual, patente_actual),
            eli_fila_despacho('Conductor', conductor, patente_actual),
            eli_fila_despacho('Estado SAP Draft', eli_estado_sap_despacho(draft_status, update_status), patente_actual),
            eli_fila_despacho('DocEntry', update_status.get('docentry') or draft_status.get('docentry'), patente_actual),
            eli_fila_despacho('DocNum', update_status.get('docnum') or draft_status.get('docnum'), patente_actual),
        ], eli_auditoria_despacho(log_draft, 'Asistente C D')),
        eli_etapa(2, 'Datos SAP despacho', [
            eli_fila_despacho('Draft SAP DocEntry', update_status.get('docentry') or draft_status.get('docentry'), patente_actual),
            eli_fila_despacho('Draft SAP DocNum', update_status.get('docnum') or draft_status.get('docnum'), patente_actual),
            eli_fila_despacho('Estado Draft SAP', eli_estado_sap_despacho(draft_status, update_status), patente_actual),
            eli_fila_despacho('Series', sap_resumen.get('series'), patente_actual),
            eli_fila_despacho('DocObjectCode', sap_resumen.get('doc_object_code'), patente_actual),
            eli_fila_despacho('CardCode', sap_resumen.get('card_code'), patente_actual),
            eli_fila_despacho('CardName', cliente_nombre, patente_actual),
            eli_fila_despacho('AgreementNo interno usado en SAP', sap_resumen.get('agreement_no'), patente_actual),
            eli_fila_despacho('Numero acuerdo visible', sap_resumen.get('agreement_visible'), patente_actual),
            eli_fila_despacho('Linea acuerdo', sap_resumen.get('linea_acuerdo'), patente_actual),
            eli_fila_despacho('ItemCode', sap_resumen.get('item_code'), patente_actual),
            eli_fila_despacho('ItemName', producto, patente_actual),
            eli_fila_despacho('WarehouseCode', sap_resumen.get('warehouse_code'), patente_actual),
            eli_fila_despacho('BatchNumber', sap_resumen.get('batch_number'), patente_actual),
            eli_fila_despacho('Quantity inicial', sap_resumen.get('quantity_inicial'), patente_actual),
            eli_fila_despacho('Quantity actualizado con peso salida', sap_resumen.get('quantity_actualizada'), patente_actual),
            eli_fila_despacho('Fecha/hora creacion draft', draft_status.get('fecha_hora'), patente_actual),
            eli_fila_despacho('Usuario creacion draft', draft_status.get('usuario'), patente_actual),
            eli_fila_despacho('Fecha/hora actualizacion draft', update_status.get('fecha_hora'), patente_actual),
            eli_fila_despacho('Usuario actualizacion draft', update_status.get('usuario'), patente_actual),
            eli_fila_despacho('Mensaje', 'Borrador SAP actualizado con peso de salida. Confirmacion final queda a cargo del equipo SAP.' if update_status.get('updated') else update_status.get('resumen_mensaje'), patente_actual),
        ], eli_auditoria_despacho(log_update or log_draft, 'Asistente Recepcion')),
        eli_etapa(3, 'Flujo operacional despacho', [
            eli_fila_despacho('Pesaje Entrada', eli_observacion_despacho(log_pesaje_entrada, patente_actual) or 'Peso entrada registrado', patente_actual),
            eli_fila_despacho('Autorizacion Salida Inicial', eli_observacion_despacho(log_autorizacion_inicial, patente_actual), patente_actual),
            eli_fila_despacho('Ingreso Planta', eli_observacion_despacho(log_ingreso_planta, patente_actual), patente_actual),
            eli_fila_despacho('Pesaje Salida', eli_observacion_despacho(log_pesaje_salida, patente_actual) or 'Peso salida registrado', patente_actual),
            eli_fila_despacho('Actualizacion Documento SAP', eli_observacion_despacho(log_update, patente_actual) or eli_estado_sap_despacho(draft_status, update_status), patente_actual),
            eli_fila_despacho('Autorizacion Salida', eli_observacion_despacho(log_autorizar, patente_actual), patente_actual),
            eli_fila_despacho('Confirmar Salida', eli_observacion_despacho(log_confirmar, patente_actual), patente_actual),
        ], eli_auditoria_despacho(log_confirmar or log_autorizar, 'Operacion Planta')),
        eli_etapa(4, 'Pesajes', [
            eli_fila_despacho('Peso entrada', peso_entrada, patente_actual),
            eli_fila_despacho('Peso salida', peso_salida, patente_actual),
            eli_fila_despacho('Diferencia', diferencia_peso, patente_actual),
            eli_fila_despacho('Ticket entrada', eli_ticket_row(ticket_ent, 'nombre_archivo_pdf'), patente_actual),
            eli_fila_despacho('Ticket salida', eli_ticket_row(ticket_sal, 'nombre_archivo_pdf'), patente_actual),
            eli_fila_despacho('Fecha/hora pesaje entrada', eli_ticket_row(ticket_ent, 'fecha_hora_ticket') or eli_fecha_vacia(log_pesaje_entrada.OPL_FFECHAREGISTRO if log_pesaje_entrada else None), patente_actual),
            eli_fila_despacho('Usuario pesaje entrada', eli_usuario_vacio(log_pesaje_entrada.US_NID) if log_pesaje_entrada else '', patente_actual),
            eli_fila_despacho('Fecha/hora pesaje salida', eli_ticket_row(ticket_sal, 'fecha_hora_ticket') or eli_fecha_vacia(log_pesaje_salida.OPL_FFECHAREGISTRO if log_pesaje_salida else None), patente_actual),
            eli_fila_despacho('Usuario pesaje salida', eli_usuario_vacio(log_pesaje_salida.US_NID) if log_pesaje_salida else '', patente_actual),
        ], eli_auditoria_despacho(log_pesaje_salida, 'Operador Romana')),
        eli_etapa(5, 'Cierre operacional despacho', [
            eli_fila_despacho('Peso entrada', peso_entrada, patente_actual),
            eli_fila_despacho('Peso salida', peso_salida, patente_actual),
            eli_fila_despacho('Diferencia', diferencia_peso, patente_actual),
            eli_fila_despacho('Fecha salida planta', eli_fecha_vacia(log_confirmar.OPL_FFECHAREGISTRO if log_confirmar else None), patente_actual),
            eli_fila_despacho('Responsable', 'Guardia Porteria', patente_actual),
            eli_fila_despacho('Estado', log_confirmar.OPL_CESTADO if log_confirmar else 'Pendiente', patente_actual),
            eli_fila_despacho('Aprobado por', eli_usuario_vacio(log_confirmar.US_NID) if log_confirmar else '', patente_actual),
            eli_fila_despacho('Observacion final', eli_observacion_despacho(log_confirmar, patente_actual), patente_actual),
            eli_fila_despacho('Resultado final', 'Camion salio de planta.' if log_confirmar else 'Pendiente confirmar salida.', patente_actual),
        ], eli_auditoria_despacho(log_confirmar, 'Guardia Porteria')),
    ]

    seguimiento = []
    flujo_pasos = [
        ('Pesaje Entrada', log_pesaje_entrada, 'Peso entrada registrado'),
        ('Autorizacion Salida Inicial', log_autorizacion_inicial, 'Salida inicial autorizada'),
        ('Ingreso Planta', log_ingreso_planta, 'Ingreso/reingreso autorizado'),
        ('Pesaje Salida', log_pesaje_salida, 'Peso salida registrado'),
        ('Creacion borrador SAP despacho', log_draft, f'Draft DocEntry: {draft_status.get("docentry") or ""} | DocNum: {draft_status.get("docnum") or ""} | CardCode: {sap_resumen.get("card_code") or ""} | Producto: {producto} | Quantity inicial: {sap_resumen.get("quantity_inicial") or ""} | AgreementNo: {sap_resumen.get("agreement_no") or ""} | WarehouseCode: {sap_resumen.get("warehouse_code") or ""} | BatchNumber: {sap_resumen.get("batch_number") or ""}'),
        ('Actualizacion borrador SAP con peso salida', log_update, f'Draft DocEntry: {update_status.get("docentry") or ""} | Peso salida usado: {peso_salida or ""} | Quantity actualizado: {sap_resumen.get("quantity_actualizada") or ""} | Estado: {update_status.get("result_label") or ""}'),
        ('Autorizacion Salida', log_autorizar, 'Salida autorizada'),
        ('Confirmar Salida', log_confirmar, 'Camion salio de planta.'),
    ]
    for idx, (paso, log, resultado) in enumerate(flujo_pasos, start=1):
        seguimiento.append({
            'numero': idx,
            'paso': paso,
            'perfil': log.OPL_CPERFIL_RESPONSABLE if log else '',
            'estado': log.OPL_CESTADO if log else 'PENDIENTE',
            'usuario': eli_usuario(log.US_NID) if log else '',
            'fecha': eli_fecha(log.OPL_FFECHAREGISTRO) if log else '',
            'observacion': eli_limpiar_texto_despacho(resultado or eli_observacion_despacho(log, patente_actual), patente_actual),
            'detalles': [],
        })

    tiempos = [
        {'nombre': 'Tiempo total del proceso', 'valor': eli_duracion(citacion.CI_FFECHAREGISTRO or citacion.CI_FFECHACITACION, log_confirmar.OPL_FFECHAREGISTRO if log_confirmar else citacion.CI_FFECHATERMINO)},
        {'nombre': 'Pesaje Entrada a Pesaje Salida', 'valor': eli_duracion(log_pesaje_entrada.OPL_FFECHAREGISTRO if log_pesaje_entrada else None, log_pesaje_salida.OPL_FFECHAREGISTRO if log_pesaje_salida else None)},
        {'nombre': 'Pesaje Salida a Actualizacion SAP', 'valor': eli_duracion(log_pesaje_salida.OPL_FFECHAREGISTRO if log_pesaje_salida else None, log_update.OPL_FFECHAREGISTRO if log_update else None)},
        {'nombre': 'Autorizacion Salida a Confirmar Salida', 'valor': eli_duracion(log_autorizar.OPL_FFECHAREGISTRO if log_autorizar else None, log_confirmar.OPL_FFECHAREGISTRO if log_confirmar else None)},
    ]
    datos_camion = [
        {'label': 'Transportista', 'value': transportista},
        {'label': 'Conductor', 'value': conductor},
        {'label': 'Patente', 'value': patente_actual},
        {'label': 'Telefono', 'value': normalizar_celular_conductor_visible(telefono)},
        {'label': 'Guia', 'value': citacion.CI_CNUMERODOCUMENTO},
    ]
    datos_planificacion = [
        {'label': 'Cliente SAP / CardName', 'value': cliente_nombre},
        {'label': 'CardCode', 'value': sap_resumen.get('card_code')},
        {'label': 'OC Cliente / NumAtCard', 'value': oc_cliente},
        {'label': 'Codigo producto SAP', 'value': codigo_producto},
        {'label': 'Producto SAP', 'value': producto},
        {'label': 'Contrato SAP visible', 'value': sap_resumen.get('agreement_visible')},
        {'label': 'SAP AbsID / AgreementNo interno', 'value': sap_resumen.get('agreement_no')},
        {'label': 'Cantidad intentada', 'value': cantidad_intentada},
    ]

    pdf_disponible = bool(log_confirmar or log_autorizar)
    return {
        'citacion': citacion,
        'detalle': detalle_despacho,
        'item': item,
        'encabezado_eli': encabezado_eli,
        'etapas_eli': etapas_eli,
        'documentos': documentos,
        'etapa_logs': [],
        'seguimiento': seguimiento,
        'datos_operacion': [],
        'tiempos': tiempos,
        'datos_camion': datos_camion,
        'datos_planificacion': datos_planificacion,
        'pdf_disponible': pdf_disponible,
        'estado_eli': 'Final disponible' if pdf_disponible else 'Preliminar',
        'resumen': {
            'producto': producto,
            'patente': patente_actual,
            'transportista': transportista,
            'conductor': conductor,
            'peso_entrada': peso_entrada,
            'peso_salida': peso_salida,
            'diferencia_peso': diferencia_peso,
            'resultado_calidad': '',
            'recepcion_conforme': '',
            'estado_final': citacion.CI_CESTADO,
            'usuario_autoriza': log_autorizar.US_NID.username if log_autorizar and log_autorizar.US_NID else '',
            'usuario_confirma': log_confirmar.US_NID.username if log_confirmar and log_confirmar.US_NID else '',
        },
    }


def construir_archivo_eli(citacion, request=None):
    if es_citacion_despacho(citacion):
        return construir_archivo_eli_despacho(citacion, request=request)

    sincronizar_expediente_legacy_citacion(citacion)
    detalle = obtener_detalle_operacional_citacion(citacion)
    detalle_dict = detalle_operacional_dict(citacion)
    valores_ingreso = obtener_valores_ingreso_camion(citacion)
    item = CITACION_ITEM.objects.select_related('IT_NID').filter(CI_NID=citacion).first()
    datos_operacion_qs = DATO_OPERACION.objects.select_related('CAMP_NID', 'US_NID', 'ET_NID').filter(
        CI_NID=citacion
    ).order_by('DO_FFECHAREGISTRO', 'id')
    datos_operacion = list(datos_operacion_qs)
    datos_por_codigo = {}
    for dato in datos_operacion:
        codigo = dato.CAMP_NID.CA_CCODIGO if dato.CAMP_NID else f'DATO_{dato.id}'
        datos_por_codigo[codigo] = dato

    documentos = []
    for documento in CITACION_DOCUMENTO.objects.select_related('US_SUBE_NID').filter(
        CI_NID=citacion,
        EP_NID=citacion.EP_NID,
        CD_BACTIVO=True
    ).order_by('CD_CTIPO', '-CD_FFECHASUBIDA'):
        documentos.append({
            'id': documento.id,
            'tipo': documento.get_CD_CTIPO_display(),
            'codigo': documento.CD_CTIPO,
            'archivo': os.path.basename(documento.CD_CNOMBRE_ARCHIVO or documento.CD_CRUTA_ARCHIVO or ''),
            'fecha': eli_fecha(documento.CD_FFECHASUBIDA),
            'usuario': eli_usuario(documento.US_SUBE_NID),
        })

    etapa_logs = []
    for idx, log in enumerate(ETAPA_LOG.objects.select_related(
        'ET_NID', 'US_INICIO_ID', 'US_FIN_ID'
    ).filter(CI_NID=citacion).order_by('EL_FFECHAINICIO', 'id'), start=1):
        etapa_logs.append({
            'numero': idx,
            'accion': log.EL_CACCION or (log.ET_NID.ET_CNOMBRE if log.ET_NID else ''),
            'etapa': log.ET_NID.ET_CNOMBRE if log.ET_NID else '',
            'usuario_inicio': eli_usuario(log.US_INICIO_ID),
            'usuario_fin': eli_usuario(log.US_FIN_ID),
            'inicio': eli_fecha(log.EL_FFECHAINICIO),
            'fin': eli_fecha(log.EL_FFECHAFIN),
            'observacion': log.EL_COBSERVACION or '',
            'duracion': eli_duracion(log.EL_FFECHAINICIO, log.EL_FFECHAFIN),
        })

    logs_operacion = list(OPERACION_PLANTA_LOG.objects.select_related('US_NID').filter(
        CI_NID=citacion
    ).order_by('OPL_FFECHAREGISTRO', 'id'))
    seguimiento = []
    for idx, log in enumerate(logs_operacion, start=1):
        metadata_log = eli_parse_json_seguro(log.OPL_COBSERVACION)
        detalle_rows = eli_metadata_rows(metadata_log) if isinstance(metadata_log, dict) else []
        codigo_por_paso = {
            'Pesaje Entrada': _codigo_campo_ticket_pesaje('ENT'),
            'Pesaje Salida': _codigo_campo_ticket_pesaje('SAL'),
            PASO_TOMA_MUESTRA: CAMPO_TOMA_MUESTRA_ACCION,
            PASO_ANALISIS_CALIDAD: CAMPO_RESULTADO_CALIDAD,
            PASO_RESULTADO_CALIDAD: CAMPO_PREPARACION_DESCARGA,
            PASO_CICLO_DESCARGA: CAMPO_CICLO_DESCARGA,
            PASO_AUTORIZAR_SALIDA: CAMPO_AUTORIZAR_SALIDA,
        }.get(log.OPL_CPASO)
        if codigo_por_paso:
            metadata_dato = eli_dato_metadata(datos_por_codigo, codigo_por_paso)
            detalle_rows = eli_metadata_rows(metadata_dato) or detalle_rows
        seguimiento.append({
            'numero': idx,
            'paso': log.OPL_CPASO,
            'perfil': log.OPL_CPERFIL_RESPONSABLE,
            'estado': log.OPL_CESTADO,
            'usuario': eli_usuario(log.US_NID),
            'fecha': eli_fecha(log.OPL_FFECHAREGISTRO),
            'observacion': log.OPL_COBSERVACION or '',
            'detalles': detalle_rows,
        })

    datos_operacion_rows = []
    for dato in datos_operacion:
        codigo_dato = dato.CAMP_NID.CA_CCODIGO if dato.CAMP_NID else f'DATO_{dato.id}'
        metadata = eli_parse_json_seguro(dato.DO_CVALOR)
        datos_operacion_rows.append({
            'codigo': codigo_dato,
            'etiqueta': dato.CAMP_NID.CA_CETIQUETA if dato.CAMP_NID else '',
            'valor': '' if isinstance(metadata, dict) else (
                normalizar_celular_conductor_visible(dato.DO_CVALOR)
                if codigo_dato == 'ING_TELEFONO_CONDUCTOR'
                else dato.DO_CVALOR
            ),
            'detalles': eli_metadata_rows(metadata) if isinstance(metadata, dict) else [],
            'usuario': eli_usuario(dato.US_NID),
            'fecha': eli_fecha(dato.DO_FFECHAREGISTRO),
        })

    ticket_ent = eli_dato_metadata(datos_por_codigo, _codigo_campo_ticket_pesaje('ENT'))
    ticket_sal = eli_dato_metadata(datos_por_codigo, _codigo_campo_ticket_pesaje('SAL'))
    calidad = eli_dato_metadata(datos_por_codigo, CAMPO_RESULTADO_CALIDAD)
    preparacion = eli_dato_metadata(datos_por_codigo, CAMPO_PREPARACION_DESCARGA)
    autorizacion = eli_dato_metadata(datos_por_codigo, CAMPO_AUTORIZAR_SALIDA)
    ciclo = eli_dato_metadata(datos_por_codigo, CAMPO_CICLO_DESCARGA)

    log_habilita = eli_primer_log_operacion(logs_operacion, 'Habilitar Operacion Planta')
    log_pesaje_entrada = eli_primer_log_operacion(logs_operacion, 'Pesaje Entrada')
    log_toma_muestra = eli_primer_log_operacion(logs_operacion, PASO_TOMA_MUESTRA)
    log_analisis = eli_primer_log_operacion(logs_operacion, PASO_ANALISIS_CALIDAD)
    log_resultado = eli_primer_log_operacion(logs_operacion, PASO_RESULTADO_CALIDAD)
    log_inicio_descarga = eli_primer_log_operacion(logs_operacion, 'INICIA_DESCARGA')
    log_ciclo = eli_primer_log_operacion(logs_operacion, PASO_CICLO_DESCARGA)
    log_pesaje_salida = eli_primer_log_operacion(logs_operacion, 'Pesaje Salida')
    log_autorizar = eli_primer_log_operacion(logs_operacion, PASO_AUTORIZAR_SALIDA)
    log_confirmar = eli_primer_log_operacion(logs_operacion, PASO_CONFIRMAR_SALIDA)

    tiempos = [
        {'nombre': 'Tiempo total del proceso', 'valor': eli_duracion(citacion.CI_FFECHAREGISTRO or citacion.CI_FFECHACITACION, log_confirmar.OPL_FFECHAREGISTRO if log_confirmar else citacion.CI_FFECHATERMINO)},
        {'nombre': 'Ingreso camion hasta habilitar operacion planta', 'valor': eli_duracion(citacion.CI_FFECHAINICIO or citacion.CI_FFECHAREGISTRO, log_habilita.OPL_FFECHAREGISTRO if log_habilita else None)},
        {'nombre': 'Pesaje Entrada a Toma de muestra', 'valor': eli_duracion(log_pesaje_entrada.OPL_FFECHAREGISTRO if log_pesaje_entrada else None, log_toma_muestra.OPL_FFECHAREGISTRO if log_toma_muestra else None)},
        {'nombre': 'Toma de muestra a Analisis Calidad', 'valor': eli_duracion(log_toma_muestra.OPL_FFECHAREGISTRO if log_toma_muestra else None, log_analisis.OPL_FFECHAREGISTRO if log_analisis else None)},
        {'nombre': 'Analisis Calidad a Resultado Calidad', 'valor': eli_duracion(log_analisis.OPL_FFECHAREGISTRO if log_analisis else None, log_resultado.OPL_FFECHAREGISTRO if log_resultado else None)},
        {'nombre': 'Resultado Calidad a Inicio Descarga', 'valor': eli_duracion(log_resultado.OPL_FFECHAREGISTRO if log_resultado else None, log_inicio_descarga.OPL_FFECHAREGISTRO if log_inicio_descarga else None)},
        {'nombre': 'Duracion real Ciclo Descarga', 'valor': ciclo.get('duracion_legible') or (log_ciclo and log_ciclo.OPL_COBSERVACION) or 'No disponible'},
        {'nombre': 'Pesaje Salida a Autorizar Salida', 'valor': eli_duracion(log_pesaje_salida.OPL_FFECHAREGISTRO if log_pesaje_salida else None, log_autorizar.OPL_FFECHAREGISTRO if log_autorizar else None)},
        {'nombre': 'Autorizar Salida a Confirmar Salida', 'valor': eli_duracion(log_autorizar.OPL_FFECHAREGISTRO if log_autorizar else None, log_confirmar.OPL_FFECHAREGISTRO if log_confirmar else None)},
        {'nombre': 'Tiempo total en planta', 'valor': eli_duracion(log_habilita.OPL_FFECHAREGISTRO if log_habilita else None, log_confirmar.OPL_FFECHAREGISTRO if log_confirmar else None)},
    ]

    datos_camion = [
        {'label': 'Transportista', 'value': valores_ingreso.get('transportista')},
        {'label': 'Conductor', 'value': valores_ingreso.get('conductor')},
        {'label': 'Patente', 'value': valores_ingreso.get('patente')},
        {'label': 'Ejes', 'value': valores_ingreso.get('cantidad_ejes')},
        {'label': 'Telefono', 'value': valores_ingreso.get('celular_conductor')},
        {'label': 'Guia', 'value': citacion.CI_CNUMERODOCUMENTO},
        {'label': 'Contenedor / BL', 'value': valores_ingreso.get('bl') or detalle_dict.get('bl')},
        {'label': 'Estanque destino', 'value': detalle_dict.get('estanque_destino') or ciclo.get('estanque_destino')},
    ]
    proveedor_sap_eli = (
        detalle_dict.get('proveedor_sap')
        or valor_dato_operacion(datos_por_codigo, 'PLAN_PROVEEDOR_SAP')
        or (citacion.PRO_NID.SN_CRAZONSOCIAL if citacion.PRO_NID else '')
    )
    codigo_proveedor_sap_eli = (
        detalle_dict.get('proveedor_codigo')
        or valor_dato_operacion(datos_por_codigo, 'PLAN_CODIGO_PROVEEDOR_SAP')
    )
    contrato_sap = (
        valor_dato_operacion(datos_por_codigo, 'PLAN_CONTRATO_SAP')
        or obtener_contrato_sap_visible_por_pedido(detalle_dict.get('pedido'))
    )

    datos_planificacion = [
        {'label': 'Insumo SAP', 'value': detalle_dict.get('insumo') or (item.IT_NID.IT_CNOMBRE if item and item.IT_NID else '')},
        {'label': 'Codigo SAP', 'value': detalle_dict.get('codigo')},
        {'label': 'Pedido SAP', 'value': detalle_dict.get('pedido')},
        {'label': 'Proveedor SAP', 'value': proveedor_sap_eli},
        {'label': 'Codigo proveedor SAP', 'value': codigo_proveedor_sap_eli},
        {'label': 'Contrato SAP', 'value': contrato_sap},
        {'label': 'BL/contenedor', 'value': detalle_dict.get('bl')},
        {'label': 'Cantidad', 'value': detalle_dict.get('cantidad_disponible')},
        {'label': 'Planta/almacen', 'value': detalle_dict.get('almacen_destino')},
        {'label': 'Ruta/tarifa', 'value': (citacion.TAR_NID.TAR_CNOMBRETARIFA if citacion.TAR_NID else '')},
        {'label': 'Tipo flete', 'value': citacion.CI_CTIPO_FLETE},
        {'label': 'Fecha planificacion', 'value': eli_fecha(citacion.PL_NID.PL_FFECHAINICIO if citacion.PL_NID else None)},
    ]

    insumo_sap = detalle_dict.get('insumo') or (item.IT_NID.IT_CNOMBRE if item and item.IT_NID else '')
    numero_documento = citacion.CI_CNUMERODOCUMENTO or ''
    tipo_documento = str(citacion.CI_CTIPODOCUMENTO or '').upper()
    guia = numero_documento if 'FACT' not in tipo_documento else ''
    factura = numero_documento if 'FACT' in tipo_documento else ''
    observacion_toma_muestra = _observacion_toma_muestra_visible(citacion, log_toma_muestra)
    peso_entrada = ticket_ent.get('peso_neto')
    peso_salida = ticket_sal.get('peso_neto')
    diferencia_peso = ''
    try:
        if peso_entrada not in [None, ''] and peso_salida not in [None, '']:
            diferencia_peso = Decimal(str(peso_entrada)) - Decimal(str(peso_salida))
    except (InvalidOperation, ValueError):
        diferencia_peso = ''

    encabezado_eli = [
        eli_fila('Numero citacion', citacion.id),
        eli_fila('Fecha citacion', eli_fecha_solo_dia_vacia(citacion.CI_FFECHACITACION)),
        eli_fila('Cliente', citacion.SN_NID.SN_CRAZONSOCIAL if citacion.SN_NID else ''),
        eli_fila('Proveedor', proveedor_sap_eli),
        eli_fila('Tipo recepcion', citacion.CI_CTIPO),
        eli_fila('Flujo', citacion.SC_NID.SE_CNOMBRE if citacion.SC_NID else ''),
        eli_fila('Patente', valores_ingreso.get('patente')),
        eli_fila('Conductor', valores_ingreso.get('conductor')),
        eli_fila('Transportista', valores_ingreso.get('transportista')),
    ]

    etapas_eli = [
        eli_etapa(1, 'Revision documental', [
            eli_fila('Guia', guia),
            eli_fila('Factura', factura),
            eli_fila('Cliente', citacion.SN_NID.SN_CRAZONSOCIAL if citacion.SN_NID else ''),
            eli_fila('Codigo SAP', detalle_dict.get('codigo')),
            eli_fila('Pedido SAP', detalle_dict.get('pedido')),
            eli_fila('Contrato SAP', contrato_sap),
            eli_fila('Insumo SAP', insumo_sap),
            eli_fila('Cantidad neta', detalle_dict.get('cantidad_disponible')),
            eli_fila('Transportista', valores_ingreso.get('transportista')),
            eli_fila('Patente', valores_ingreso.get('patente')),
            eli_fila('Conductor', valores_ingreso.get('conductor')),
        ], eli_auditoria_operacion(None, 'Asistente Recepcion')),
        eli_etapa(2, 'Ingreso a planta', [
            eli_fila('Fecha ingreso', eli_fecha_vacia(log_habilita.OPL_FFECHAREGISTRO if log_habilita else None)),
            eli_fila('Usuario que autorizo ingreso', eli_usuario_vacio(log_habilita.US_NID) if log_habilita else ''),
            eli_fila('Observaciones', log_habilita.OPL_COBSERVACION if log_habilita else ''),
        ], eli_auditoria_operacion(log_habilita, 'Guardia Porteria')),
        eli_etapa(3, 'Inspeccion transporte', [
            eli_fila('Estado camion', ''),
            eli_fila('Estado carga', ''),
            eli_fila('Sellos', ''),
            eli_fila('Contaminacion', ''),
            eli_fila('Observaciones', ''),
        ], eli_auditoria_operacion(None, '')),
        eli_etapa(4, 'Toma de muestra', [
            eli_fila('Observacion toma de muestra', observacion_toma_muestra),
        ], eli_auditoria_operacion(log_toma_muestra, 'Asistente C_D')),
        eli_etapa(5, 'Analisis y calidad', [
            eli_fila('Resultado calidad', calidad.get('resultado_calidad')),
            eli_fila('Observacion calidad', calidad.get('comentario')),
            eli_fila('Documento laboratorio', calidad.get('documento_nombre')),
        ], eli_auditoria_operacion(log_analisis, 'Calidad')),
        eli_etapa(6, 'Autorizacion descarga', [
            eli_fila('Autoriza descarga', preparacion.get('autoriza_descarga')),
            eli_fila('Observaciones', preparacion.get('observaciones_descarga')),
        ], eli_auditoria_operacion(log_resultado, 'Asistente C_D')),
        eli_etapa(7, 'Descarga', [
            eli_fila('Numero sellos', ''),
            eli_fila('Estado camion', ''),
            eli_fila('Facil apertura', ''),
            eli_fila('Observaciones', ''),
        ], eli_auditoria_operacion(log_ciclo or log_inicio_descarga, 'Sala Control')),
        eli_etapa(8, 'Cierre operacional', [
            eli_fila('Pesaje entrada', peso_entrada),
            eli_fila('Pesaje salida', peso_salida),
            eli_fila('Diferencia', diferencia_peso),
            eli_fila('Fecha salida planta', eli_fecha_vacia(log_confirmar.OPL_FFECHAREGISTRO if log_confirmar else None)),
        ], eli_auditoria_operacion(log_confirmar, 'Guardia Porteria')),
    ]

    pdf_disponible = bool(log_autorizar)
    return {
        'citacion': citacion,
        'detalle': detalle,
        'item': item,
        'encabezado_eli': encabezado_eli,
        'etapas_eli': etapas_eli,
        'documentos': documentos,
        'etapa_logs': etapa_logs,
        'seguimiento': seguimiento,
        'datos_operacion': datos_operacion_rows,
        'tiempos': tiempos,
        'datos_camion': datos_camion,
        'datos_planificacion': datos_planificacion,
        'pdf_disponible': pdf_disponible,
        'estado_eli': 'Final disponible' if pdf_disponible else 'Preliminar',
        'resumen': {
            'producto': insumo_sap,
            'patente': valores_ingreso.get('patente'),
            'transportista': valores_ingreso.get('transportista'),
            'conductor': valores_ingreso.get('conductor'),
            'peso_entrada': peso_entrada,
            'peso_salida': peso_salida,
            'diferencia_peso': diferencia_peso,
            'resultado_calidad': calidad.get('resultado_calidad'),
            'recepcion_conforme': autorizacion.get('recepcion_conforme'),
            'estado_final': citacion.CI_CESTADO,
            'usuario_autoriza': log_autorizar.US_NID.username if log_autorizar and log_autorizar.US_NID else '',
            'usuario_confirma': log_confirmar.US_NID.username if log_confirmar and log_confirmar.US_NID else '',
        },
    }


def ELI_LISTALL(request):
    empresa = Verificar_empresa(request)
    if empresa is None:
        messages.error(request, 'Debe seleccionar una empresa activa')
        return redirect('/')
    if not usuario_puede_ver_archivo_eli(request.user):
        messages.error(request, 'No tiene permisos para Archivo E.L.I.')
        return redirect('/')

    autorizadas_ids = OPERACION_PLANTA_LOG.objects.filter(
        EP_NID_id=empresa,
        OPL_CPASO=PASO_AUTORIZAR_SALIDA,
        OPL_CESTADO=OPERACION_PLANTA_LOG.ESTADO_COMPLETADO
    ).values_list('CI_NID_id', flat=True)
    citaciones = CITACION.objects.select_related(
        'EP_NID', 'PL_NID', 'SN_NID', 'PRO_NID', 'CON_NID', 'CA_NID', 'detalle_operacional'
    ).filter(
        EP_NID_id=empresa,
        CI_BHABILITADO=True
    ).filter(Q(CI_CESTADO=CIT_TERMINADO) | Q(id__in=autorizadas_ids))

    citacion_filtro = str(request.GET.get('citacion') or '').strip()
    if citacion_filtro:
        if citacion_filtro.isdigit():
            citaciones = citaciones.filter(id=citacion_filtro)
        else:
            citaciones = citaciones.none()

    citaciones = citaciones.order_by('-CI_FFECHACITACION', '-id')
    paginator = Paginator(citaciones, 30)
    page_obj = paginator.get_page(request.GET.get('page'))
    querystring = request.GET.copy()
    querystring.pop('page', None)

    rows = []
    autorizadas_set = set(autorizadas_ids)
    for citacion in page_obj.object_list:
        valores = obtener_valores_ingreso_camion(citacion)
        item = CITACION_ITEM.objects.select_related('IT_NID').filter(CI_NID=citacion).first()
        detalle = getattr(citacion, 'detalle_operacional', None)
        proveedor_sap = (detalle.CDO_CPRODUCTOR if detalle else '') or (citacion.PRO_NID.SN_CRAZONSOCIAL if citacion.PRO_NID else '')
        rows.append({
            'citacion': citacion,
            'patente': valores.get('patente'),
            'transportista': valores.get('transportista'),
            'conductor': valores.get('conductor'),
            'producto': (detalle.CDO_CINSUMO if detalle else '') or (item.IT_NID.IT_CNOMBRE if item and item.IT_NID else ''),
            'cliente_proveedor': proveedor_sap or (citacion.SN_NID.SN_CRAZONSOCIAL if citacion.SN_NID else ''),
            'estado_eli': 'Final disponible' if citacion.id in autorizadas_set else 'Preliminar',
            'pdf_disponible': citacion.id in autorizadas_set,
        })

    return render(request, 'home/ELI/eli_listall.html', {
        'page_obj': page_obj,
        'rows': rows,
        'filtros': request.GET,
        'querystring': querystring.urlencode(),
    })


